        settingsScroll->setMaximumWidth(365);
        settingsScroll->setSizeAdjustPolicy(QAbstractScrollArea::AdjustToContents);
        settingsScroll->setSizePolicy(QSizePolicy::Fixed, QSizePolicy::Maximum);
        previewSettingsPanel_->setSizePolicy(QSizePolicy::Preferred, QSizePolicy::Maximum);
        previewSettingsScroll_ = settingsScroll;
        settingsScroll->setVisible(true);

        // IMPORTANT: do not parent the floating inspector into the same widget
        // hierarchy as the Direct3D preview. D3DPreviewWidget owns a native
        // HWND (WA_NativeWindow + WA_PaintOnScreen). On Windows, shrinking an
        // ordinary Qt child overlay above that native child can leave stale Qt
        // backing-store pixels behind until some unrelated repaint occurs. The
        // symptom is an exact ghost copy of the old Advanced controls after
        // switching back to Beginner mode. Make the inspector an owned top-level
        // tool window instead. Windows then composites the inspector and D3D
        // child as separate HWNDs, so exposing/shrinking the inspector cannot
        // burn stale pixels into the preview area.
        previewSettingsOverlayHost_ = new QWidget(this, Qt::Tool | Qt::FramelessWindowHint);
        previewSettingsOverlayHost_->setObjectName("PreviewSettingsOverlayHost");
        previewSettingsOverlayHost_->setAttribute(Qt::WA_StyledBackground, false);
        previewSettingsOverlayHost_->setAttribute(Qt::WA_TranslucentBackground, true);
        previewSettingsOverlayHost_->setAutoFillBackground(false);
        previewSettingsOverlayHost_->setSizePolicy(QSizePolicy::Maximum, QSizePolicy::Maximum);
