        settingsFloatLayout->setContentsMargins(10, 8, 10, 10);
        settingsFloatLayout->setSpacing(0);
        settingsFloatLayout->addWidget(settingsScroll, 0, Qt::AlignTop | Qt::AlignRight);
        previewSettingsOverlayHost_->hide();
        previewLayout->addLayout(previewBody, 1);

        previewSettingsToggleButton_->installEventFilter(this);
        preview_->installEventFilter(this);

        connect(closePreviewSettings, &QToolButton::clicked, this, [this]{
            if(previewSettingsScroll_) previewSettingsScroll_->hide();
            if(previewSettingsOverlayHost_) previewSettingsOverlayHost_->hide();
            if(previewSettingsToggleButton_) previewSettingsToggleButton_->setChecked(false);
        });
        connect(previewSettingsToggleButton_, &QToolButton::toggled, this, [this](bool visible){
            if(!previewSettingsScroll_) return;
            if(previewMaxButton_ && previewMaxButton_->isChecked())
            {
                previewSettingsScroll_->hide();
                if(previewSettingsOverlayHost_) previewSettingsOverlayHost_->hide();
                return;
            }
            previewSettingsScroll_->setVisible(visible);
            if(previewSettingsOverlayHost_)
            {
                previewSettingsOverlayHost_->setVisible(visible);
                if(visible)
                {
                    previewSettingsOverlayHost_->adjustSize();
                    positionPreviewSettingsPopup();
                    previewSettingsOverlayHost_->raise();
                }
            }
        });
        connect(resetInspectorButton, &QPushButton::clicked, this, [this]{
            if(preview_) preview_->renderer().ResetCamera();
            resetLightingControls();
            resetBackgroundColor();
            if(postFxContextCombo_)
            {
                const int runtimeIndex = postFxContextCombo_->findData(
                    static_cast<int>(PostFxPreviewContext::Bo3RuntimeResolvedScene));
                if(runtimeIndex >= 0) postFxContextCombo_->setCurrentIndex(runtimeIndex);
            }
            updateCameraUi();
            statusBar()->showMessage("Preview defaults restored", 2500);
        });
        connect(applyMotionRemovalButton, &QPushButton::clicked, this, [this]{
            if(!editor_) return;
            const bo3::ShaderMotionTransformResult transformed =
                bo3::removeShaderCameraInputMovement(editor_->toPlainText());
            if(!transformed.changed)
            {
                QMessageBox::information(this, "Camera / Input Motion",
                    "No recognized whole-screen camera/input motion was found in the current HLSL. The shader was not changed.");
                return;
            }

            const CodeEditor::ViewState viewState = editor_->captureViewState();
            QTextCursor cursor(editor_->document());
            cursor.beginEditBlock();
            cursor.select(QTextCursor::Document);
            cursor.insertText(transformed.source);
            cursor.endEditBlock();
            editor_->restoreViewState(viewState);
            if(disableShaderDrivenMovement_)
            {
                QSignalBlocker blocker(disableShaderDrivenMovement_);
                disableShaderDrivenMovement_->setChecked(false);
            }
            liveCompileTimer_.stop();
            compileEditor();
            statusBar()->showMessage(
                "Applied camera/input motion removal to the HLSL editor source — Ctrl+Z to undo.", 5000);
        });

        scenePanel_ = buildScenePanel();
        sourceValuesPanel_ = buildSourceValuesPanel();
        shaderParamsPanel_ = buildShaderParametersPanel();
        materialTexturesPanel_ = buildMaterialTexturesPanel();
        scriptPanel_ = buildScriptVectorPanel();
        performancePanel_ = buildPerformancePanel();

        // Tool docks must never impose their content's preferred height on the
        // main splitter. Scrolling is preferable to preventing Preview from growing.
        auto* sceneScroll = new CompactDockScrollArea(scenePanel_);
        auto* sourceValuesScroll = new CompactDockScrollArea(sourceValuesPanel_);
        auto* shaderParamsScroll = new CompactDockScrollArea(shaderParamsPanel_);
        auto* materialScroll = new CompactDockScrollArea(materialTexturesPanel_);
        auto* scriptScroll = new CompactDockScrollArea(scriptPanel_);
        auto* performanceScroll = new CompactDockScrollArea(performancePanel_);

