        connect(clearOutputButton, &QPushButton::clicked, this, [this]
        {
            compilerOutput_->clear();
            compilerOutputFullText_.clear();
            statusBar()->showMessage("Cleared Compiler Output", 1800);
        });
        connect(copyOutputButton, &QPushButton::clicked, this, [this]
        {
            QString copyText = compilerOutputFullText_.isEmpty()
                ? compilerOutput_->toPlainText()
                : compilerOutputFullText_;
            // Be defensive even if a diagnostic source accidentally reintroduces
            // embedded NUL characters in the future. Windows clipboard consumers
            // otherwise stop at the first NUL and Copy All looks truncated.
            copyText.remove(QChar('\0'));
            QApplication::clipboard()->setText(copyText, QClipboard::Clipboard);
            statusBar()->showMessage(QString("Copied all Compiler Output (%1 characters)").arg(copyText.size()), 2500);
        });

        auto makeDock = [this](const QString& title, const QString& objectName, QWidget* content, Qt::DockWidgetArea area) -> QDockWidget*
        {
            auto* dock = new QDockWidget(title, this);
            dock->setObjectName(objectName);
            dock->setAllowedAreas(Qt::AllDockWidgetAreas);
            dock->setFeatures(QDockWidget::DockWidgetMovable | QDockWidget::DockWidgetFloatable | QDockWidget::DockWidgetClosable);
            dock->setWidget(content);
            addDockWidget(area, dock);
            return dock;
        };

        previewDock_ = makeDock("Preview", "PreviewDock", previewContainer, Qt::RightDockWidgetArea);
        outputDock_ = makeDock("Console", "CompilerDock", outputContainer, Qt::BottomDockWidgetArea);
        sourceValuesDock_ = makeDock("Inputs", "SourceValuesDock", sourceValuesScroll, Qt::BottomDockWidgetArea);
        shaderParamsDock_ = makeDock("Parameters", "ShaderParamsDock", shaderParamsScroll, Qt::BottomDockWidgetArea);
        materialDock_ = makeDock("Material Textures", "MaterialDock", materialScroll, Qt::BottomDockWidgetArea);
        performanceDock_ = makeDock("Performance", "PerformanceDock", performanceScroll, Qt::BottomDockWidgetArea);
        sceneDock_ = makeDock("Scene / Lighting", "SceneDock", sceneScroll, Qt::BottomDockWidgetArea);
        scriptDock_ = makeDock("Script Vectors", "ScriptDock", scriptScroll, Qt::BottomDockWidgetArea);

        // The Preview Settings inspector is now an owned top-level tool window
        // so it can safely float above the native Direct3D HWND. Keep it tied to
        // Preview dock visibility/location so it still behaves like part of the
        // preview surface when the user changes layouts or floats the dock.
        connect(previewDock_, &QDockWidget::visibilityChanged, this, [this](bool visible){
            if(!previewSettingsOverlayHost_) return;
            if(!visible)
            {
                previewSettingsOverlayHost_->hide();
                return;
            }
            if(previewSettingsToggleButton_ && previewSettingsToggleButton_->isChecked() &&
               (!previewMaxButton_ || !previewMaxButton_->isChecked()))
            {
                previewSettingsOverlayHost_->show();
                previewSettingsOverlayHost_->adjustSize();
                QTimer::singleShot(0, this, [this]{
                    positionPreviewSettingsPopup();
                    if(previewSettingsOverlayHost_) previewSettingsOverlayHost_->raise();
                });
            }
        });
        connect(previewDock_, &QDockWidget::dockLocationChanged, this, [this](Qt::DockWidgetArea){
            if(previewSettingsOverlayHost_ && previewSettingsOverlayHost_->isVisible())
                QTimer::singleShot(0, this, [this]{ positionPreviewSettingsPopup(); });
        });
        connect(previewDock_, &QDockWidget::topLevelChanged, this, [this](bool){
            if(previewSettingsOverlayHost_ && previewSettingsOverlayHost_->isVisible())
                QTimer::singleShot(0, this, [this]{ positionPreviewSettingsPopup(); });
        });

        // Keep Preview as the large right-hand surface and make every secondary
        // tool a tab in one bottom dock area. This removes the previous stack of
        // competing panels under Preview and matches the simplified IDE layout.
        previewDock_->setAllowedAreas(Qt::LeftDockWidgetArea | Qt::RightDockWidgetArea);
        for (QDockWidget* d : {outputDock_, sourceValuesDock_, shaderParamsDock_, materialDock_, performanceDock_, sceneDock_, scriptDock_})
        {
            d->setAllowedAreas(Qt::TopDockWidgetArea | Qt::BottomDockWidgetArea);
            // The tab already names the tool. Remove the duplicate dock title bar
            // to reclaim vertical space and make the bottom area feel like one
            // intentional tab strip rather than stacked Qt dock widgets.
            auto* compactTitle = new QWidget(d);
            compactTitle->setFixedHeight(0);
            d->setTitleBarWidget(compactTitle);
        }
        for (QDockWidget* d : {previewDock_, sceneDock_, sourceValuesDock_, shaderParamsDock_, materialDock_, scriptDock_, performanceDock_, outputDock_})
        {
            d->setMinimumSize(0, 0);
            d->setSizePolicy(QSizePolicy::Ignored, QSizePolicy::Ignored);
        }

        tabifyDockWidget(outputDock_, sourceValuesDock_);
        tabifyDockWidget(sourceValuesDock_, shaderParamsDock_);
        tabifyDockWidget(shaderParamsDock_, materialDock_);
        tabifyDockWidget(materialDock_, performanceDock_);
        tabifyDockWidget(performanceDock_, sceneDock_);
        tabifyDockWidget(sceneDock_, scriptDock_);
