        layout->setSpacing(8);

        auto* intro = new QLabel("Editable numeric constants and #defines detected in this HLSL appear here.");
        intro->setWordWrap(false);
        intro->setObjectName("CompactHelp");
        intro->setToolTip(
            "Changing a control edits the actual shader source, so Live Update previews it immediately. Descriptions use nearby // comments when available.");
        layout->addWidget(intro);

        auto* searchRow = new QHBoxLayout();
        sourceValueFilter_ = new QLineEdit();
        sourceValueFilter_->setPlaceholderText("Filter values... e.g. cloud, speed, color, steps");
        sourceValuesCountLabel_ = new QLabel("0 values");
        auto* refresh = new QPushButton("Refresh");
        auto* undo = new QPushButton("Undo value edit");
        searchRow->addWidget(sourceValueFilter_, 1);
        searchRow->addWidget(sourceValuesCountLabel_);
        searchRow->addWidget(refresh);
        searchRow->addWidget(undo);
        layout->addLayout(searchRow);

        sourceValuesDynamic_ = new QWidget();
        sourceValuesLayout_ = new QVBoxLayout(sourceValuesDynamic_);
        sourceValuesLayout_->setContentsMargins(0, 0, 0, 0);
        sourceValuesLayout_->setSpacing(8);
        layout->addWidget(sourceValuesDynamic_);
