    void refreshSourceValueControls()
    {
        if (!sourceValuesLayout_ || !editor_) return;
        while (QLayoutItem* item = sourceValuesLayout_->takeAt(0))
        {
            if (QWidget* widget = item->widget()) widget->deleteLater();
            delete item;
        }

        const QVector<SourceTweakValue> values = scanSourceTweakValues();
        const QString filter = sourceValueFilter_ ? sourceValueFilter_->text().trimmed() : QString();
        int shown = 0;
        for (const SourceTweakValue& value : values)
        {
            if (!filter.isEmpty() &&
                !value.name.contains(filter, Qt::CaseInsensitive) &&
                !humanizeShaderName(value.name).contains(filter, Qt::CaseInsensitive) &&
                !value.description.contains(filter, Qt::CaseInsensitive))
                continue;

            auto* group = new QGroupBox(humanizeShaderName(value.name));
            auto* groupLayout = new QVBoxLayout(group);
            groupLayout->setContentsMargins(8, 8, 8, 8);
            groupLayout->setSpacing(5);

            auto* codeName = new QLabel(QString("<code>%1 %2</code>").arg(value.type.toHtmlEscaped(), value.name.toHtmlEscaped()));
            codeName->setTextFormat(Qt::RichText);
            codeName->setStyleSheet("QLabel { color:#8EA0B5; }");
            groupLayout->addWidget(codeName);

            auto* description = new QLabel(value.description);
            description->setWordWrap(true);
            description->setStyleSheet("QLabel { color:#B9C0CA; }");
            groupLayout->addWidget(description);

            if (value.isBool)
            {
                auto* box = new QCheckBox("Enabled");
                box->setChecked(value.values.value(0) >= 0.5);
                box->setToolTip("This directly changes the HLSL value.");
                connect(box, &QCheckBox::toggled, this, [this, value](bool checked){
                    replaceSourceTweakValue(value, QVector<double>{checked ? 1.0 : 0.0});
                });
                groupLayout->addWidget(box, 0, Qt::AlignLeft);
            }
            else
            {
                auto* row = new QHBoxLayout();
                QVector<QDoubleSpinBox*> boxes;
                static const char* vectorComponents[] = {"X", "Y", "Z", "W"};
                static const char* colorComponents[] = {"R", "G", "B", "A"};
                const bool colorLike = value.name.contains("color", Qt::CaseInsensitive) || value.name.contains("tint", Qt::CaseInsensitive);
                for (int i = 0; i < value.values.size(); ++i)
                {
                    if (value.values.size() > 1) row->addWidget(new QLabel((colorLike ? colorComponents : vectorComponents)[std::min(i, 3)]));
                    auto* spin = new QDoubleSpinBox();
                    double mn = -10000.0, mx = 10000.0, step = 0.01;
                    suggestedSourceValueRange(value, value.values[i], mn, mx, step);
                    spin->setRange(mn, mx);
                    spin->setSingleStep(step);
                    spin->setDecimals(value.isInteger ? 0 : 8);
                    spin->setKeyboardTracking(false);
                    spin->setValue(value.values[i]);
                    spin->setMinimumWidth(100);
                    boxes.push_back(spin);
                    row->addWidget(spin, value.values.size() == 1 ? 1 : 0);
                }
                row->addStretch(value.values.size() > 1 ? 1 : 0);
                groupLayout->addLayout(row);

                for (QDoubleSpinBox* spin : boxes)
                {
                    connect(spin, qOverload<double>(&QDoubleSpinBox::valueChanged), this, [this, value, boxes](double){
                        QVector<double> updated;
                        updated.reserve(boxes.size());
                        for (QDoubleSpinBox* b : boxes) updated.push_back(b->value());
                        replaceSourceTweakValue(value, updated);
                    });
                }
            }

            sourceValuesLayout_->addWidget(group);
            ++shown;
        }

        if (shown == 0)
        {
            auto* none = new QLabel(filter.isEmpty()
                ? "No editable numeric values detected in this shader."
                : "No shader values match this filter.");
            none->setWordWrap(true);
            sourceValuesLayout_->addWidget(none);
        }
        sourceValuesLayout_->addStretch(1);
        if (sourceValuesCountLabel_)
            sourceValuesCountLabel_->setText(QString("%1 value%2").arg(shown).arg(shown == 1 ? "" : "s"));
    }

    QWidget* buildShaderParametersPanel()
    {
        auto* panel = new QWidget();
        auto* layout = new QVBoxLayout(panel);
        layout->setContentsMargins(8, 8, 8, 8);
        layout->setSpacing(8);
        auto* intro = new QLabel("Runtime values reflected from the shader. BO3 normally supplies many of these from the material/tool at runtime, so a shader can compile correctly but look unchanged when these values are zero.");
        intro->setWordWrap(true);
        layout->addWidget(intro);
        shaderParamsDynamic_ = new QWidget();
        shaderParamsForm_ = new QFormLayout(shaderParamsDynamic_);
        shaderParamsForm_->setContentsMargins(0,0,0,0);
        shaderParamsForm_->setHorizontalSpacing(10);
        shaderParamsForm_->setVerticalSpacing(6);
        layout->addWidget(shaderParamsDynamic_);
        auto* reset = new QPushButton("Reset preview parameter values");
        connect(reset, &QPushButton::clicked, this, [this]{
            preview_->renderer().ResetShaderParameters();
            refreshShaderParameterControls();
            statusBar()->showMessage("Shader parameter preview values reset", 2500);
        });
        layout->addWidget(reset, 0, Qt::AlignLeft);
        layout->addStretch(1);
        return panel;
    }

    void refreshShaderParameterControls()
    {
        if (!shaderParamsForm_ || !preview_) return;
        while (shaderParamsForm_->rowCount() > 0) shaderParamsForm_->removeRow(0);
        const auto params = preview_->renderer().EditableShaderParameters();
        if (params.empty())
        {
            auto* none = new QLabel("No editable scalar runtime parameters were reflected from this shader.");
            none->setWordWrap(true);
            shaderParamsForm_->addRow(none);
            return;
        }
        for (const auto& param : params)
        {
            const QString name = QString::fromStdString(param.name);
            if (param.isBool)
            {
                auto* box = new QCheckBox();
                box->setChecked(param.value != 0.0f);
                connect(box, &QCheckBox::toggled, this, [this, n=param.name](bool checked){ preview_->renderer().SetShaderParameter(n, checked ? 1.0f : 0.0f); });
                shaderParamsForm_->addRow(name, box);
            }
            else
            {
                auto* spin = new QDoubleSpinBox();
                spin->setDecimals(4);
                spin->setRange(-10000.0, 10000.0);
                spin->setSingleStep(0.05);
                spin->setKeyboardTracking(true);
                spin->setValue(param.value);
                connect(spin, qOverload<double>(&QDoubleSpinBox::valueChanged), this, [this, n=param.name](double value){ preview_->renderer().SetShaderParameter(n, static_cast<float>(value)); });
                shaderParamsForm_->addRow(name, spin);
            }
        }
    }

    QWidget* buildScriptVectorPanel()
    {
        auto* panel = new QWidget();
        auto* layout = new QVBoxLayout(panel);
        auto* intro = new QLabel("Detected BO3 GenericsCBuffer script vectors. Values update the preview immediately without recompiling.");
        intro->setWordWrap(true);
        layout->addWidget(intro);

        auto* grid = new QGridLayout();
        grid->addWidget(new QLabel("Vector"), 0, 0);
        const char* comps[] = {"X", "Y", "Z", "W"};
        for (int c = 0; c < 4; ++c) grid->addWidget(new QLabel(comps[c]), 0, c + 1);
        for (int v = 0; v < 8; ++v)
        {
            vectorLabels_[v] = new QLabel(QString("scriptVector%1").arg(v));
            grid->addWidget(vectorLabels_[v], v + 1, 0);
            for (int c = 0; c < 4; ++c)
            {
                auto* box = new QDoubleSpinBox();
                box->setDecimals(4);
                box->setRange(-10000.0, 10000.0);
                box->setSingleStep(0.1);
                box->setKeyboardTracking(false);
                vectorBoxes_[v][c] = box;
                grid->addWidget(box, v + 1, c + 1);
                connect(box, qOverload<double>(&QDoubleSpinBox::valueChanged), this, [this, v, c](double value){
                    if (refreshingVectors_) return;
                    preview_->renderer().SetScriptVectorComponent(v, c, static_cast<float>(value));
                });
            }
        }
        layout->addLayout(grid);
        auto* reset = new QPushButton("Reset values to preview defaults");
        connect(reset, &QPushButton::clicked, this, [this]{
            preview_->renderer().ResetScriptVectorOverrides();
            refreshScriptVectorControls();
        });
        layout->addWidget(reset);
        vectorInfo_ = new QLabel("Compile a shader to detect scriptVector0-7.");
        vectorInfo_->setWordWrap(true);
        layout->addWidget(vectorInfo_);
        layout->addStretch(1);
        return panel;
    }

