    QWidget* buildMaterialTexturesPanel()
    {
        auto* panel = new QWidget();
        auto* outer = new QVBoxLayout(panel);
        outer->setContentsMargins(8, 8, 8, 8);
        outer->setSpacing(8);

        auto* intro = new QLabel(
            "Use Shadertoy / GLSL Texture Inputs for iChannel0..3 in converted 2D shaders. "
            "Material texture slots below are for Forward Material and Deferred / GBuffer modes.\n"
            "Shadertoy channels are separate from BO3 frameBuffer/depth bindings so texture-driven effects preview correctly.");
        intro->setWordWrap(true);
        intro->setStyleSheet("QLabel { color:#B9C0CA; }");
        outer->addWidget(intro);

        auto* shadertoyGroup = new QGroupBox("Shadertoy / GLSL Texture Inputs");
        auto* shadertoyLayout = new QVBoxLayout(shadertoyGroup);
        auto* shadertoyHelp = new QLabel(
            "Load the exact textures assigned to iChannel0..3 on Shadertoy. GLSL source contains only channel names, not the image bytes, so the converter cannot recreate or download those textures automatically. "
            "Mipmaps are generated automatically; match each channel's Filter / Wrap / VFlip settings from Shadertoy.");
        shadertoyHelp->setWordWrap(true);
        shadertoyHelp->setStyleSheet("QLabel { color:#9AA3AE; }");
        shadertoyLayout->addWidget(shadertoyHelp);

        for (int channel = 0; channel < kShadertoyChannelCount; ++channel)
        {
            auto* row = new QHBoxLayout();
            auto* name = new QLabel(QString("iChannel%1").arg(channel));
            name->setMinimumWidth(78);
            row->addWidget(name, 0);

            auto* pathLabel = new QLabel("No texture loaded");
            pathLabel->setMinimumWidth(220);
            pathLabel->setMinimumHeight(30);
            pathLabel->setAlignment(Qt::AlignVCenter | Qt::AlignLeft);
            pathLabel->setContentsMargins(8, 0, 8, 0);
            pathLabel->setStyleSheet("QLabel { color:#9AA3AE; border:1px dashed #4B5563; border-radius:5px; background:#171A1F; }");
            shadertoyChannelPathLabels_[channel] = pathLabel;
            row->addWidget(pathLabel, 1);

            auto* repeat = new QCheckBox("Repeat");
            repeat->setChecked(true);
            repeat->setToolTip("Use wrap/repeat addressing for this Shadertoy channel.");
            shadertoyChannelRepeatBoxes_[channel] = repeat;
            row->addWidget(repeat, 0);

            auto* flip = new QCheckBox("Flip Y");
            flip->setChecked(true);
            flip->setToolTip("Vertically flip the image when loading. Shadertoy marks many built-in textures as vflipped.");
            shadertoyChannelFlipBoxes_[channel] = flip;
            row->addWidget(flip, 0);

            auto* browse = new QPushButton("Browse...");
            auto* clear = new QPushButton("Clear");
            row->addWidget(browse, 0);
            row->addWidget(clear, 0);
            shadertoyLayout->addLayout(row);

            connect(repeat, &QCheckBox::toggled, this, [this, channel](bool enabled){
                if (preview_) preview_->renderer().SetShadertoyChannelRepeat(channel, enabled);
            });
            connect(flip, &QCheckBox::toggled, this, [this, channel](bool){
                reloadShadertoyChannelTexture(channel);
            });
            connect(browse, &QPushButton::clicked, this, [this, channel]{ browseShadertoyChannelTexture(channel); });
            connect(clear, &QPushButton::clicked, this, [this, channel]{ clearShadertoyChannelTexture(channel); });
        }
        outer->addWidget(shadertoyGroup);

        auto* uvGroup = new QGroupBox("Geometry UV Tiling");
        auto* uvOuter = new QVBoxLayout(uvGroup);
        auto* uvHelp = new QLabel("Change how large the texture appears on Sphere / Cube / Plane previews without editing the shader. 1.0 = normal, 2.0 = tile twice, 0.5 = make the texture twice as large. Directional sky shaders use these values as equirectangular tiling instead of treating mesh UVs as XYZ directions.");
        uvHelp->setWordWrap(true);
        uvHelp->setStyleSheet("QLabel { color:#9AA3AE; }");
        uvOuter->addWidget(uvHelp);
        auto* uvRow = new QHBoxLayout();
        auto* uvU = new QDoubleSpinBox();
        auto* uvV = new QDoubleSpinBox();
        auto* uvLock = new QCheckBox("Lock U/V");
        auto* uvReset = new QPushButton("Reset 1:1");
        for (auto* spin : {uvU, uvV})
        {
            spin->setDecimals(3);
            spin->setRange(0.05, 64.0);
            spin->setSingleStep(0.1);
            spin->setKeyboardTracking(true);
            spin->setMinimumWidth(90);
        }
        QSettings uvSettings("OpenAI", "BO3HLSLPreviewer");
        const double initialU = uvSettings.value("preview/uvScaleU", 1.0).toDouble();
        const double initialV = uvSettings.value("preview/uvScaleV", 1.0).toDouble();
        uvU->setValue(std::clamp(initialU, 0.05, 64.0));
        uvV->setValue(std::clamp(initialV, 0.05, 64.0));
        uvLock->setChecked(uvSettings.value("preview/uvScaleLocked", true).toBool());
        if (preview_) preview_->renderer().SetMaterialUvScale(static_cast<float>(uvU->value()), static_cast<float>(uvV->value()));
        uvRow->addWidget(new QLabel("U"));
        uvRow->addWidget(uvU);
        uvRow->addWidget(new QLabel("V"));
        uvRow->addWidget(uvV);
        uvRow->addWidget(uvLock);
        uvRow->addWidget(uvReset);
        uvRow->addStretch(1);
        uvOuter->addLayout(uvRow);
        outer->addWidget(uvGroup);

        const auto applyUvTiling = [this, uvU, uvV]
        {
            if (preview_) preview_->renderer().SetMaterialUvScale(static_cast<float>(uvU->value()), static_cast<float>(uvV->value()));
            QSettings s("OpenAI", "BO3HLSLPreviewer");
            s.setValue("preview/uvScaleU", uvU->value());
            s.setValue("preview/uvScaleV", uvV->value());
        };
        connect(uvU, qOverload<double>(&QDoubleSpinBox::valueChanged), this, [uvV, uvLock, applyUvTiling](double value){
            if (uvLock->isChecked()) { QSignalBlocker blocker(uvV); uvV->setValue(value); }
            applyUvTiling();
        });
        connect(uvV, qOverload<double>(&QDoubleSpinBox::valueChanged), this, [uvU, uvLock, applyUvTiling](double value){
            if (uvLock->isChecked()) { QSignalBlocker blocker(uvU); uvU->setValue(value); }
            applyUvTiling();
        });
        connect(uvLock, &QCheckBox::toggled, this, [uvU, uvV, applyUvTiling](bool locked){
            QSettings s("OpenAI", "BO3HLSLPreviewer");
            s.setValue("preview/uvScaleLocked", locked);
            if (locked) { QSignalBlocker blocker(uvV); uvV->setValue(uvU->value()); applyUvTiling(); }
        });
        connect(uvReset, &QPushButton::clicked, this, [uvU, uvV, applyUvTiling]{
            { QSignalBlocker b1(uvU); QSignalBlocker b2(uvV); uvU->setValue(1.0); uvV->setValue(1.0); }
            applyUvTiling();
        });

        auto* header = new QHBoxLayout();
        header->addWidget(new QLabel("Texture"), 2);
        header->addWidget(new QLabel("Preview binding"), 0);
        header->addWidget(new QLabel("Loaded file"), 3);
        outer->addLayout(header);

        for (int i = 0; i < kMaterialTextureSlotCount; ++i)
        {
            auto* row = new QHBoxLayout();
            auto* name = new QLabel(MaterialTextureSlotName(i));
            name->setMinimumWidth(130);
            row->addWidget(name, 0);

            auto* bindBox = new QComboBox();
            for (int slot = 0; slot <= 15; ++slot)
                bindBox->addItem(QString("t%1").arg(slot), slot);
            bindBox->setCurrentIndex(static_cast<int>(DefaultMaterialTextureBinding(i)));
            bindBox->setToolTip("Select which shader texture register this texture should occupy during preview.");
            materialTextureBindingBoxes_[i] = bindBox;
            row->addWidget(bindBox, 0);

            auto* pathLabel = new QLabel("Drop image here  •  or Browse...");
            pathLabel->setMinimumWidth(250);
            pathLabel->setMinimumHeight(34);
            pathLabel->setAlignment(Qt::AlignVCenter | Qt::AlignLeft);
            pathLabel->setContentsMargins(10, 0, 10, 0);
            pathLabel->setAcceptDrops(true);
            pathLabel->setProperty("materialTextureSlot", i);
            pathLabel->installEventFilter(this);
            pathLabel->setStyleSheet("QLabel { color:#9AA3AE; border:1px dashed #4B5563; border-radius:5px; background:#171A1F; }");
            pathLabel->setToolTip(QString("Drop an image here to use it as %1.").arg(MaterialTextureSlotName(i)));
            materialTexturePathLabels_[i] = pathLabel;
            row->addWidget(pathLabel, 1);

            auto* browse = new QPushButton("Browse...");
            auto* clear = new QPushButton("Clear");
            row->addWidget(browse, 0);
            row->addWidget(clear, 0);
            outer->addLayout(row);

            connect(bindBox, qOverload<int>(&QComboBox::currentIndexChanged), this, [this, i, bindBox](int){
                preview_->renderer().SetMaterialTextureBinding(i, bindBox->currentData().toUInt());
                statusBar()->showMessage(QString("%1 bound to %2").arg(MaterialTextureSlotName(i)).arg(bindBox->currentText()), 2500);
            });
            connect(browse, &QPushButton::clicked, this, [this, i]{ browseMaterialTexture(i); });
            connect(clear, &QPushButton::clicked, this, [this, i]{ clearMaterialTexture(i); });
        }

        auto* quick = new QHBoxLayout();
        auto* applyDefaults = new QPushButton("Apply recommended bindings");
        applyDefaults->setToolTip("Reset texture-slot bindings to a simple BO3-friendly default layout.");
        auto* clearAll = new QPushButton("Clear all material textures");
        quick->addWidget(applyDefaults, 0);
        quick->addWidget(clearAll, 0);
        quick->addStretch(1);
        outer->addSpacing(4);
        outer->addLayout(quick);

        connect(applyDefaults, &QPushButton::clicked, this, [this]{
            for (int i = 0; i < kMaterialTextureSlotCount; ++i)
            {
                if (materialTextureBindingBoxes_[i])
                {
                    QSignalBlocker blocker(materialTextureBindingBoxes_[i]);
                    materialTextureBindingBoxes_[i]->setCurrentIndex(static_cast<int>(DefaultMaterialTextureBinding(i)));
                }
                preview_->renderer().SetMaterialTextureBinding(i, DefaultMaterialTextureBinding(i));
            }
            statusBar()->showMessage("Applied recommended material texture bindings", 3000);
        });
        connect(clearAll, &QPushButton::clicked, this, [this]{
            for (int i = 0; i < kMaterialTextureSlotCount; ++i)
                clearMaterialTexture(i, false);
            refreshMaterialTextureUi();
            statusBar()->showMessage("Cleared all material textures", 3000);
        });

        outer->addStretch(1);
        return panel;
    }

    QWidget* buildPerformancePanel()
    {
        auto* panel = new QWidget();
        auto* layout = new QVBoxLayout(panel);
        layout->setSpacing(10);

        auto* intro = new QLabel(
            "Live BO3 shader performance estimate. GPU pass time is measured with Direct3D 11 timestamp queries; "
            "the target-resolution estimate scales that measured pass by pixel count.");
        intro->setWordWrap(true);
        layout->addWidget(intro);

        auto* targetRow = new QHBoxLayout();
        targetResolution_ = new QComboBox();
        targetResolution_->addItem("1280 × 720", QSize(1280, 720));
        targetResolution_->addItem("1920 × 1080", QSize(1920, 1080));
        targetResolution_->addItem("2560 × 1440", QSize(2560, 1440));
        targetResolution_->addItem("3840 × 2160", QSize(3840, 2160));
        targetResolution_->setCurrentIndex(1);
        targetFps_ = new QComboBox();
        targetFps_->addItems({"30 FPS", "60 FPS", "120 FPS", "144 FPS", "165 FPS", "240 FPS"});
        targetFps_->setCurrentText("60 FPS");
        targetRow->addWidget(new QLabel("Target:"));
        targetRow->addWidget(targetResolution_);
        targetRow->addSpacing(8);
        targetRow->addWidget(new QLabel("Frame rate:"));
        targetRow->addWidget(targetFps_);
        targetRow->addStretch(1);
        layout->addLayout(targetRow);

        auto* grid = new QGridLayout();
        int row = 0;
        auto addMetric = [&](const QString& name, QLabel*& value)
        {
            auto* key = new QLabel(name);
            value = new QLabel("--");
            value->setTextInteractionFlags(Qt::TextSelectableByMouse);
            grid->addWidget(key, row, 0);
            grid->addWidget(value, row, 1);
            ++row;
        };
        addMetric("GPU", perfGpuName_);
        addMetric("Preview FPS", perfLiveFps_);
        addMetric("Measured shader pass", perfGpuMs_);
        addMetric("Measured preview pixels", perfPreviewResolution_);
        addMetric("Estimated target pass", perfTargetEstimate_);
        addMetric("Frame budget used", perfBudget_);
        addMetric("Shader instructions", perfInstructions_);
        addMetric("Texture instructions", perfTextureOps_);
        addMetric("Temporary registers", perfTempRegisters_);
        addMetric("Dynamic flow-control ops", perfDynamicFlow_);
        layout->addLayout(grid);

        perfAssessment_ = new QLabel("Collecting GPU timing...");
        perfAssessment_->setObjectName("performanceAssessment");
        perfAssessment_->setWordWrap(true);
        perfAssessment_->setMinimumHeight(52);
        layout->addWidget(perfAssessment_);

        auto* caveat = new QLabel(
            "Important: this estimates the cost of this shader pass on your current GPU, not total BO3 FPS. "
            "The game also renders geometry, lighting, shadows, other post effects, UI, CPU work, and may run "
            "the shader at a different resolution. Use this as a headroom/relative-cost check, not an exact in-game benchmark.");
        caveat->setWordWrap(true);
        caveat->setObjectName("performanceCaveat");
        layout->addWidget(caveat);
        layout->addStretch(1);

        connect(targetResolution_, qOverload<int>(&QComboBox::currentIndexChanged), this, [this]{ updatePerformanceUi(); });
        connect(targetFps_, qOverload<int>(&QComboBox::currentIndexChanged), this, [this]{ updatePerformanceUi(); });
        return panel;
    }

    void updatePerformanceUi()
    {
        if (!preview_) return;
        const auto& renderer = preview_->renderer();
        const float fps = renderer.PreviewFps();
        const float gpuMs = renderer.GpuPassMs();
        if(captureDiagnosticsLabel_)
        {
            const bo3::LiveCaptureDiagnostics capture = renderer.LiveCaptureInfo();
            const bool showCapture = renderer.IsLiveCaptureSource();
            captureDiagnosticsLabel_->setVisible(showCapture);
            if(showCapture)
            {
                captureDiagnosticsLabel_->setText(QString("%1  %2×%3  %4 fps  ~%5 ms")
                    .arg(bo3::toString(capture.state)).arg(capture.width).arg(capture.height)
                    .arg(capture.captureFps, 0, 'f', 0)
                    .arg(capture.approximateLatencyMs, 0, 'f', 1));
                captureDiagnosticsLabel_->setStyleSheet(
                    capture.state == bo3::LiveCaptureState::Capturing ||
                    capture.state == bo3::LiveCaptureState::Resizing
                        ? "QLabel { color:#76D49B; font-weight:600; }"
                        : "QLabel { color:#E6BE55; font-weight:600; }");
                captureDiagnosticsLabel_->setToolTip(capture.message +
                    "\nCapture is a display/LDR approximation, not raw BO3 resolvedScene.");
            }
        }

        if (fpsLabel_)
            fpsLabel_->setText(fps > 0.0f ? QString("%1 FPS").arg(fps, 0, 'f', 0) : "FPS --");
        if (gpuQuickLabel_)
            gpuQuickLabel_->setText(gpuMs > 0.0f ? QString("%1 ms GPU").arg(gpuMs, 0, 'f', 2) : "GPU -- ms");

        if (!perfGpuName_) return;
        perfGpuName_->setText(QString::fromStdWString(renderer.AdapterName()));
        if (!renderer.GpuTimingSupported())
        {
            perfLiveFps_->setText(fps > 0.0f ? QString("%1 FPS").arg(fps, 0, 'f', 1) : "--");
            perfGpuMs_->setText("GPU timestamp queries unavailable");
            perfPreviewResolution_->setText("--");
            perfTargetEstimate_->setText("--");
            perfBudget_->setText("--");
            const auto& stats = renderer.PerformanceStats();
            perfInstructions_->setText(stats.instructionCount ? QString::number(stats.instructionCount) : "--");
            perfTextureOps_->setText(QString::number(stats.TextureInstructionCount()));
            perfTempRegisters_->setText(stats.tempRegisterCount ? QString::number(stats.tempRegisterCount) : "--");
            perfDynamicFlow_->setText(QString::number(stats.dynamicFlowControlCount));
            perfAssessment_->setText("GPU timing is unavailable on this Direct3D device. Shader instruction statistics are still shown, but an in-game cost estimate cannot be calculated.");
            perfAssessment_->setStyleSheet("font-weight: 700; color: #DCDCAA;");
            return;
        }
        perfLiveFps_->setText(fps > 0.0f ? QString("%1 FPS").arg(fps, 0, 'f', 1) : "Collecting...");
        perfGpuMs_->setText(gpuMs > 0.0f ? QString("%1 ms").arg(gpuMs, 0, 'f', 3) : "Collecting...");
        const UINT previewW = renderer.LastViewportWidth();
        const UINT previewH = renderer.LastViewportHeight();
        perfPreviewResolution_->setText(previewW && previewH
            ? QString("%1 × %2 (%3 Mpx)").arg(previewW).arg(previewH)
                  .arg((static_cast<double>(previewW) * previewH) / 1000000.0, 0, 'f', 2)
            : "--");

        const QSize target = targetResolution_ ? targetResolution_->currentData().toSize() : QSize(1920, 1080);
        bool fpsOk = false;
        int targetFpsValue = targetFps_ ? targetFps_->currentText().section(' ', 0, 0).toInt(&fpsOk) : 60;
        if (!fpsOk || targetFpsValue <= 0) targetFpsValue = 60;
        const float frameBudgetMs = 1000.0f / static_cast<float>(targetFpsValue);
        const float estimateMs = renderer.EstimatedGpuPassMs(
            static_cast<UINT>(std::max(1, target.width())),
            static_cast<UINT>(std::max(1, target.height())));

        perfTargetEstimate_->setText(estimateMs > 0.0f
            ? QString("%1 ms at %2 × %3").arg(estimateMs, 0, 'f', 3).arg(target.width()).arg(target.height())
            : "Collecting...");
        const float budgetPercent = estimateMs > 0.0f ? (estimateMs / frameBudgetMs) * 100.0f : 0.0f;
        perfBudget_->setText(estimateMs > 0.0f
            ? QString("%1% of %2 ms").arg(budgetPercent, 0, 'f', 1).arg(frameBudgetMs, 0, 'f', 2)
            : "--");

        const auto& stats = renderer.PerformanceStats();
        perfInstructions_->setText(stats.instructionCount ? QString::number(stats.instructionCount) : "--");
        perfTextureOps_->setText(stats.TextureInstructionCount() ? QString::number(stats.TextureInstructionCount()) : "0");
        perfTempRegisters_->setText(stats.tempRegisterCount ? QString::number(stats.tempRegisterCount) : "--");
        perfDynamicFlow_->setText(QString::number(stats.dynamicFlowControlCount));

        if (estimateMs <= 0.0f)
        {
            perfAssessment_->setText("COLLECTING — leave the Preview visible for a moment so GPU timing can settle.");
            perfAssessment_->setStyleSheet("font-weight: 700; color: #DCDCAA;");
            return;
        }

        QString rating;
        QString explanation;
        QString color;
        if (budgetPercent <= 5.0f)
        {
            rating = "EXCELLENT";
            explanation = "Very light for a single full-screen pass at the selected target.";
            color = "#73C991";
        }
        else if (budgetPercent <= 10.0f)
        {
            rating = "GOOD";
            explanation = "Reasonable shader cost with healthy frame-budget headroom.";
            color = "#89D185";
        }
        else if (budgetPercent <= 20.0f)
        {
            rating = "MODERATE";
            explanation = "Noticeable cost. Usually usable, but heavy scenes or other post effects can expose it.";
            color = "#DCDCAA";
        }
        else if (budgetPercent <= 35.0f)
        {
            rating = "HEAVY";
            explanation = "Large share of the selected frame budget for one pass. Optimization is recommended.";
            color = "#E5C07B";
        }
        else
        {
            rating = "VERY HEAVY";
            explanation = "This pass alone consumes a large part of the target frame budget and is likely to hurt GPU-bound gameplay.";
            color = "#F48771";
        }
        perfAssessment_->setText(QString("%1 — estimated %2 ms, %3% of a %4 FPS frame. %5")
            .arg(rating)
            .arg(estimateMs, 0, 'f', 3)
            .arg(budgetPercent, 0, 'f', 1)
            .arg(targetFpsValue)
            .arg(explanation));
        perfAssessment_->setStyleSheet(QString("font-weight: 700; color: %1;").arg(color));
    }

    void styleNativeTitleBar()
    {
#ifdef _WIN32
        HWND hwnd = reinterpret_cast<HWND>(winId());
        HMODULE dwm = LoadLibraryW(L"dwmapi.dll");
        if (!dwm) return;
        using DwmSetWindowAttributeFn = HRESULT (WINAPI*)(HWND, DWORD, LPCVOID, DWORD);
        auto fn = reinterpret_cast<DwmSetWindowAttributeFn>(GetProcAddress(dwm, "DwmSetWindowAttribute"));
        if (fn)
        {
            const BOOL dark = currentTheme_ != "Light";
            const DWORD immersiveDarkMode = 20;
            fn(hwnd, immersiveDarkMode, &dark, sizeof(dark));
            COLORREF caption = dark ? RGB(22,24,29) : RGB(242,243,245);
            COLORREF textColor = dark ? RGB(235,238,243) : RGB(25,27,31);
            const DWORD captionColorAttr = 35;
            const DWORD textColorAttr = 36;
            fn(hwnd, captionColorAttr, &caption, sizeof(caption));
            fn(hwnd, textColorAttr, &textColor, sizeof(textColor));
        }
        FreeLibrary(dwm);
#endif
    }

    void applyTheme(const QString& name)
    {
        currentTheme_ = name;
        qApp->setStyle(QStyleFactory::create("Fusion"));

        QString window = "#12151A";
        QString panel = "#171B21";
        QString base = "#0D1014";
        QString button = "#242A32";
        QString hover = "#303844";
        QString border = "#353D49";
        QString textColor = "#E3E8EF";
        QString muted = "#9DA8B5";
        QString accent = "#4D8FCC";
        QString editorBase = "#0C0F13";

        if (name == "Graphite")
        {
            window="#181818"; panel="#202020"; base="#111111"; button="#292929"; hover="#353535"; border="#414141"; accent="#777777"; editorBase="#101010";
        }
        else if (name == "Midnight Blue")
        {
            window="#0C1420"; panel="#111D2C"; base="#07101A"; button="#182B40"; hover="#213B57"; border="#29445F"; accent="#3F8FD2"; editorBase="#08111C";
        }
        else if (name == "Light")
        {
            window="#ECEFF3"; panel="#F5F6F8"; base="#FFFFFF"; button="#E2E6EB"; hover="#D4DAE1"; border="#B8C0CA"; textColor="#1E2329"; muted="#626D78"; accent="#3178B7"; editorBase="#FFFFFF";
        }
        else if (name == "High Contrast")
        {
            window="#000000"; panel="#080808"; base="#000000"; button="#111111"; hover="#202020"; border="#E6E6E6"; textColor="#FFFFFF"; muted="#D0D0D0"; accent="#00A8FF"; editorBase="#000000";
        }

        QPalette palette;
        palette.setColor(QPalette::Window, QColor(window));
        palette.setColor(QPalette::WindowText, QColor(textColor));
        palette.setColor(QPalette::Base, QColor(base));
        palette.setColor(QPalette::AlternateBase, QColor(panel));
        palette.setColor(QPalette::ToolTipBase, QColor(panel));
        palette.setColor(QPalette::ToolTipText, QColor(textColor));
        palette.setColor(QPalette::Text, QColor(textColor));
        palette.setColor(QPalette::Button, QColor(button));
        palette.setColor(QPalette::ButtonText, QColor(textColor));
        palette.setColor(QPalette::Highlight, QColor(accent));
        palette.setColor(QPalette::HighlightedText, QColor("#FFFFFF"));
        palette.setColor(QPalette::PlaceholderText, QColor(muted));
        qApp->setPalette(palette);

        const QString qss = QString(R"QSS(
            QMainWindow, QWidget { background:%1; color:%7; }
            QMenuBar { background:%2; border-bottom:1px solid %6; padding:2px; }
            QMenuBar::item { padding:5px 9px; border-radius:4px; }
            QMenuBar::item:selected { background:%5; }
            QMenu { background:%2; border:1px solid %6; padding:4px; }
            QMenu::item { padding:6px 24px 6px 10px; border-radius:3px; }
            QMenu::item:selected { background:%9; color:#FFFFFF; }
            QToolBar { background:%2; border:0; border-bottom:1px solid %6; spacing:8px; padding:6px 8px; }
            QToolButton, QPushButton { background:%4; border:1px solid %6; border-radius:5px; padding:6px 11px; min-height:24px; }
            QToolButton:hover, QPushButton:hover { background:%5; }
            QToolButton:pressed, QPushButton:pressed { background:%9; color:#FFFFFF; }
            QLineEdit, QDoubleSpinBox, QComboBox, QKeySequenceEdit { background:%3; border:1px solid %6; border-radius:4px; padding:4px 6px; min-height:20px; }
            QComboBox::drop-down { border:0; width:20px; }
            QPlainTextEdit { background:%8; border:0; selection-background-color:%9; }
            QDockWidget { titlebar-close-icon:url(); titlebar-normal-icon:url(); }
            QDockWidget::title { background:%2; border-bottom:1px solid %6; padding:6px 8px; font-weight:600; }
            QDockWidget > QWidget { border:1px solid %6; }
            QTabWidget::pane { border:1px solid %6; }
            QTabBar::tab { background:%2; border:1px solid %6; padding:6px 12px; }
            QTabBar::tab:selected { background:%4; border-bottom-color:%4; }
            QSplitter::handle { background:%6; }
            QLabel#SectionHeader { color:%7; font-weight:700; letter-spacing:0.8px; padding:3px 2px 2px 2px; border-bottom:1px solid %6; }
            QToolButton#PrimaryAction { background:%9; color:#FFFFFF; border-color:%9; font-weight:700; }
            QToolButton#PrimaryAction:hover { background:%5; border-color:%9; }
            QToolButton#ExperienceModeButton { min-width:72px; padding:5px 10px; }
            QToolButton#ExperienceModeButton:checked { background:%9; color:#FFFFFF; border-color:%9; font-weight:700; }
            QToolButton#PreviewModeToggle { min-width:78px; padding:5px 10px; }
            QToolButton#PreviewModeToggle:checked { background:%4; border-color:%9; font-weight:600; }
            QToolButton#PreviewSettingsToggle:checked { background:%4; border-color:%9; font-weight:600; }
            QLabel#CompileStatusBadge { background:%3; border:1px solid %6; border-radius:11px; padding:4px 10px; font-weight:600; }
            QFrame#PreviewSettingsPanel { background:%2; border:1px solid %6; border-radius:7px; }
            QWidget#PreviewSettingsOverlayHost { background:transparent; }
            QScrollArea#PreviewSettingsScroll { background:transparent; border:0; }
            QPushButton#CompactConsoleButton { min-height:18px; padding:3px 8px; }
            QLabel#InspectorTitle { font-weight:700; font-size:13px; }
            QLabel#DetectedPreviewType { color:%7; font-weight:700; }
            QLabel#InspectorHelp { color:%10; }
            QLabel#CompactHelp { color:%10; padding:1px 0; }
            QGroupBox { border:1px solid %6; border-radius:6px; margin-top:10px; padding-top:8px; font-weight:600; }
            QGroupBox::title { subcontrol-origin:margin; left:8px; padding:0 5px; color:%7; }
            QStatusBar { background:%2; border-top:1px solid %6; }
            QScrollBar:vertical { background:%1; width:12px; }
            QScrollBar::handle:vertical { background:%6; min-height:28px; border-radius:5px; margin:2px; }
            QScrollBar:horizontal { background:%1; height:12px; }
            QScrollBar::handle:horizontal { background:%6; min-width:28px; border-radius:5px; margin:2px; }
            QScrollBar::add-line, QScrollBar::sub-line { width:0; height:0; }
        )QSS").arg(window, panel, base, button, hover, border, textColor, editorBase, accent, muted);
        setStyleSheet(qss);

        for (auto it = themeActions_.begin(); it != themeActions_.end(); ++it)
            if (it.value()) it.value()->setChecked(it.key() == name);
        QSettings settings("OpenAI", "BO3HLSLPreviewer");
        settings.setValue("ui/theme", name);
        styleNativeTitleBar();
    }

    void positionPreviewSettingsPopup()
    {
        if(!previewSettingsOverlayHost_ || !preview_ || !previewSettingsOverlayHost_->isVisible())
            return;

        previewSettingsOverlayHost_->adjustSize();
        QSize popupSize = previewSettingsOverlayHost_->sizeHint();
        if(!popupSize.isValid() || popupSize.isEmpty())
            popupSize = previewSettingsOverlayHost_->size();

        // Match the old in-preview drawer placement: top-right of the actual
        // render surface with a small inset. The popup is a separate owned HWND,
        // so this preserves the overlay look without mixing Qt backing-store
        // painting with the Direct3D child window.
        const QPoint previewTopLeft = preview_->mapToGlobal(QPoint(0, 0));
        const QPoint previewTopRight = preview_->mapToGlobal(QPoint(preview_->width(), 0));
        int x = previewTopRight.x() - popupSize.width() - 8;
        int y = previewTopLeft.y() + 8;

        // Keep the whole inspector reachable on small windows / multi-monitor
        // layouts. Prefer the screen containing the preview, then fall back to
        // the window's current screen.
        QScreen* screen = QGuiApplication::screenAt(previewTopRight);
        if(!screen) screen = this->screen();
        if(screen)
        {
            const QRect available = screen->availableGeometry();
            x = qBound(available.left() + 4,
                       x,
                       qMax(available.left() + 4, available.right() - popupSize.width() - 3));
            y = qBound(available.top() + 4,
                       y,
                       qMax(available.top() + 4, available.bottom() - popupSize.height() - 3));
        }

        previewSettingsOverlayHost_->move(x, y);
    }

    void setUiExperienceMode(bool beginner, bool persist = true)
    {
        beginnerUiMode_ = beginner;

        if(beginnerModeButton_)
        {
            QSignalBlocker blocker(beginnerModeButton_);
            beginnerModeButton_->setChecked(beginner);
        }
        if(advancedModeButton_)
        {
            QSignalBlocker blocker(advancedModeButton_);
            advancedModeButton_->setChecked(!beginner);
        }
        if(uiBeginnerModeAction_)
        {
            QSignalBlocker blocker(uiBeginnerModeAction_);
            uiBeginnerModeAction_->setChecked(beginner);
        }
        if(uiAdvancedModeAction_)
        {
            QSignalBlocker blocker(uiAdvancedModeAction_);
            uiAdvancedModeAction_->setChecked(!beginner);
        }

        // The inspector is an owned top-level tool window rather than a normal
        // Qt child over the native Direct3D HWND. Hide it while its contents are
        // resized so the mode transition is atomic, then show it again at the
        // same top-right preview anchor.
        const bool restorePreviewInspector =
            previewSettingsToggleButton_ && previewSettingsToggleButton_->isChecked() &&
            (!previewMaxButton_ || !previewMaxButton_->isChecked());
        if(previewSettingsOverlayHost_ && previewSettingsOverlayHost_->isVisible())
        {
            previewSettingsOverlayHost_->hide();
        }

        for(QWidget* widget : advancedOnlyWidgets_)
            if(widget) widget->setVisible(!beginner);
        for(QWidget* widget : advancedPreviewQuickWidgets_)
            if(widget) widget->setVisible(!beginner);

        if(previewSettingsTitle_)
            previewSettingsTitle_->setText(beginner ? "Preview Settings" : "Advanced Preview Settings");
        if(previewSettingsScroll_)
        {
            // Beginner mode is a compact, non-scrolling inspector page. Keeping the
            // Advanced controls in one hidden container and sizing to the real
            // Beginner content avoids clipped/stale child widgets peeking through
            // the floating overlay on high-DPI Windows layouts.
            if(previewSettingsScroll_->verticalScrollBar())
                previewSettingsScroll_->verticalScrollBar()->setValue(0);
            if(previewSettingsPanel_->layout())
            {
                previewSettingsPanel_->layout()->invalidate();
                previewSettingsPanel_->layout()->activate();
            }
            previewSettingsPanel_->adjustSize();
            const int contentHeight = qMax(1, previewSettingsPanel_->sizeHint().height());
            if(beginner)
            {
                previewSettingsScroll_->setVerticalScrollBarPolicy(Qt::ScrollBarAlwaysOff);
                previewSettingsScroll_->setMinimumHeight(contentHeight);
                previewSettingsScroll_->setMaximumHeight(contentHeight);
            }
            else
            {
                previewSettingsScroll_->setVerticalScrollBarPolicy(Qt::ScrollBarAsNeeded);
                previewSettingsScroll_->setMinimumHeight(0);
                previewSettingsScroll_->setMaximumHeight(560);
            }
            previewSettingsScroll_->viewport()->update();
            previewSettingsScroll_->updateGeometry();
            if(previewSettingsOverlayHost_)
                previewSettingsOverlayHost_->updateGeometry();
        }

        // Beginner mode removes the two most specialist bottom tabs while keeping
        // Console, Inputs, Parameters, Material Textures and Performance
        // available. Advanced mode restores the complete authoring/debug surface.
        if(beginner)
        {
            if(sceneDock_) sceneDock_->hide();
            if(scriptDock_) scriptDock_->hide();
        }
        else if(persist && (!previewMaxButton_ || !previewMaxButton_->isChecked()))
        {
            // A deliberate switch to Advanced exposes the specialist tabs. When
            // restoring a saved workspace (persist=false), preserve its visibility.
            if(sceneDock_) sceneDock_->show();
            if(scriptDock_) scriptDock_->show();
        }

        if(previewSettingsToggleButton_ && previewSettingsScroll_ &&
           (!previewMaxButton_ || !previewMaxButton_->isChecked()))
        {
            // Restore the inspector only after the mode-specific layout has been
            // fully recalculated. Repaint every layer explicitly: this is needed
            // because the panel floats over a native Direct3D child window.
            const bool showInspector = restorePreviewInspector &&
                                       previewSettingsToggleButton_->isChecked();
            previewSettingsScroll_->setVisible(showInspector);
            if(previewSettingsOverlayHost_)
            {
                previewSettingsOverlayHost_->setVisible(showInspector);
                if(showInspector)
                {
                    previewSettingsOverlayHost_->adjustSize();
                    positionPreviewSettingsPopup();
                    previewSettingsOverlayHost_->raise();
                }
            }
        }

        if(beginner && detectedPreviewModeValid_ && selectedPreviewMode() != detectedPreviewMode_)
            selectPreviewMode(detectedPreviewMode_);
        updatePreviewModeInspector();
        updateGBufferUi();
        refreshPostFxRuntimeUi();
        if(persist)
        {
            QSettings settings("OpenAI", "BO3HLSLPreviewer");
            settings.setValue("ui/experienceMode", beginner ? "Beginner" : "Advanced");
            statusBar()->showMessage(beginner
                ? "Beginner interface enabled — advanced BO3 controls are tucked into Advanced mode."
                : "Advanced interface enabled — BO3 runtime and compatibility controls are available.", 3200);
        }
    }

    void applyWorkspacePreset(const QString& preset)
    {
        if (!previewDock_ || !sceneDock_ || !sourceValuesDock_ || !shaderParamsDock_ ||
            !materialDock_ || !scriptDock_ || !performanceDock_ || !outputDock_) return;

        for (QDockWidget* d : {previewDock_, outputDock_, sourceValuesDock_, shaderParamsDock_,
                               materialDock_, performanceDock_, sceneDock_, scriptDock_})
        {
            d->setFloating(false);
            d->show();
        }

        addDockWidget(Qt::RightDockWidgetArea, previewDock_);
        addDockWidget(Qt::BottomDockWidgetArea, outputDock_);
        addDockWidget(Qt::BottomDockWidgetArea, sourceValuesDock_);
        addDockWidget(Qt::BottomDockWidgetArea, shaderParamsDock_);
        addDockWidget(Qt::BottomDockWidgetArea, materialDock_);
        addDockWidget(Qt::BottomDockWidgetArea, performanceDock_);
        addDockWidget(Qt::BottomDockWidgetArea, sceneDock_);
        addDockWidget(Qt::BottomDockWidgetArea, scriptDock_);

        tabifyDockWidget(outputDock_, sourceValuesDock_);
        tabifyDockWidget(sourceValuesDock_, shaderParamsDock_);
        tabifyDockWidget(shaderParamsDock_, materialDock_);
        tabifyDockWidget(materialDock_, performanceDock_);
        tabifyDockWidget(performanceDock_, sceneDock_);
        tabifyDockWidget(sceneDock_, scriptDock_);

        if (preset == "Material")
        {
            materialDock_->raise();
            resizeDocks({previewDock_}, {1080}, Qt::Horizontal);
            resizeDocks({materialDock_}, {210}, Qt::Vertical);
        }
        else if (preset == "Authoring")
        {
            outputDock_->raise();
            resizeDocks({previewDock_}, {950}, Qt::Horizontal);
            resizeDocks({outputDock_}, {190}, Qt::Vertical);
        }
        else if (preset == "Minimal")
        {
            for(QDockWidget* d : {outputDock_, sourceValuesDock_, shaderParamsDock_, materialDock_,
                                  performanceDock_, sceneDock_, scriptDock_})
                d->hide();
            previewDock_->show();
            resizeDocks({previewDock_}, {1100}, Qt::Horizontal);
        }
        else
        {
            outputDock_->raise();
            resizeDocks({previewDock_}, {1020}, Qt::Horizontal);
            resizeDocks({outputDock_}, {145}, Qt::Vertical);
        }

        // Interface mode owns specialist visibility even when a workspace preset
        // is selected, so switching layouts never reintroduces beginner clutter.
        setUiExperienceMode(beginnerUiMode_, false);
        statusBar()->showMessage(preset + " workspace applied", 2200);
    }

    void setPreviewMaximized(bool enabled)
    {
        if (!previewDock_) return;
        const std::array<QDockWidget*, 7> tools{outputDock_, sourceValuesDock_, shaderParamsDock_, materialDock_, performanceDock_, sceneDock_, scriptDock_};
        if (enabled)
        {
            for (size_t i = 0; i < tools.size(); ++i)
            {
                previewToolVisibility_[i] = tools[i] && tools[i]->isVisible();
                if (tools[i]) tools[i]->hide();
            }
            previewSettingsWasVisibleBeforeMax_ = previewSettingsScroll_ && previewSettingsScroll_->isVisible();
            if(previewSettingsScroll_) previewSettingsScroll_->hide();
            if(previewSettingsOverlayHost_) previewSettingsOverlayHost_->hide();
            if(previewSettingsToggleButton_) previewSettingsToggleButton_->setEnabled(false);
            if (previewMaxButton_) previewMaxButton_->setText("Restore Tools");
            previewDock_->raise();
        }
        else
        {
            bool restoredAny = false;
            for (size_t i = 0; i < tools.size(); ++i)
            {
                if (tools[i] && previewToolVisibility_[i])
                {
                    tools[i]->show();
                    restoredAny = true;
                }
            }
            if (!restoredAny && outputDock_) outputDock_->show();
            setUiExperienceMode(beginnerUiMode_, false);
            if(previewSettingsToggleButton_) previewSettingsToggleButton_->setEnabled(true);
            if(previewSettingsScroll_ && previewSettingsToggleButton_ &&
               previewSettingsWasVisibleBeforeMax_ && previewSettingsToggleButton_->isChecked())
                previewSettingsScroll_->show();
            if(previewSettingsOverlayHost_ && previewSettingsWasVisibleBeforeMax_ &&
               previewSettingsToggleButton_ && previewSettingsToggleButton_->isChecked())
            {
                previewSettingsOverlayHost_->show();
                previewSettingsOverlayHost_->adjustSize();
                QTimer::singleShot(0, this, [this]{
                    positionPreviewSettingsPopup();
                    if(previewSettingsOverlayHost_) previewSettingsOverlayHost_->raise();
                });
            }
            if (outputDock_ && outputDock_->isVisible()) outputDock_->raise();
            if (previewMaxButton_) previewMaxButton_->setText("Full Preview");
            QTimer::singleShot(0, this, [this]{
                if (outputDock_ && outputDock_->isVisible())
                    resizeDocks({outputDock_}, {145}, Qt::Vertical);
            });
        }
    }

    void saveWorkspace()
    {
        QSettings s("OpenAI", "BO3HLSLPreviewer");
        s.setValue("ui/geometry_v107", saveGeometry());
        s.setValue("ui/state_v107", saveState(13));
        statusBar()->showMessage("Workspace saved", 2200);
    }

    bool restoreWorkspace(bool showMessage = false)
    {
        QSettings s("OpenAI", "BO3HLSLPreviewer");
        const QByteArray geometry = s.value("ui/geometry_v107").toByteArray();
        const QByteArray state = s.value("ui/state_v107").toByteArray();
        bool restored = false;
        if (!geometry.isEmpty()) restored = restoreGeometry(geometry) || restored;
        if (!state.isEmpty()) restored = restoreState(state, 13) || restored;
        if (showMessage)
            statusBar()->showMessage(restored ? "Saved workspace restored" : "No saved workspace has been created yet", 2200);
        return restored;
    }

    void showKeybindDialog()
    {
        QDialog dialog(this);
        dialog.setWindowTitle("Keybinds");
        dialog.resize(520, 420);
        auto* layout = new QVBoxLayout(&dialog);
        auto* intro = new QLabel("Click a shortcut and press the new key combination. Changes apply immediately and are saved.");
        intro->setWordWrap(true);
        layout->addWidget(intro);
        auto* form = new QFormLayout();
        QMap<QString, QKeySequenceEdit*> editors;
        for (auto it = shortcutDefaults_.begin(); it != shortcutDefaults_.end(); ++it)
        {
            auto* edit = new QKeySequenceEdit(shortcutSequence(it.key()));
            editors[it.key()] = edit;
            form->addRow(it.key(), edit);
        }
        layout->addLayout(form);
        auto* buttons = new QDialogButtonBox(QDialogButtonBox::Save | QDialogButtonBox::RestoreDefaults | QDialogButtonBox::Cancel);
        layout->addWidget(buttons);
        connect(buttons->button(QDialogButtonBox::RestoreDefaults), &QPushButton::clicked, &dialog, [this, &editors]{
            for (auto it = editors.begin(); it != editors.end(); ++it)
                it.value()->setKeySequence(shortcutDefaults_.value(it.key()));
        });
        connect(buttons, &QDialogButtonBox::accepted, &dialog, [&]{
            QSettings s("OpenAI", "BO3HLSLPreviewer");
            for (auto it = editors.begin(); it != editors.end(); ++it)
            {
                const QKeySequence seq = it.value()->keySequence();
                s.setValue("keybinds/" + it.key(), seq.toString(QKeySequence::PortableText));
                if (shortcuts_.contains(it.key()) && shortcuts_[it.key()]) shortcuts_[it.key()]->setKey(seq);
            }
            dialog.accept();
        });
        connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
        dialog.exec();
    }

    QKeySequence shortcutSequence(const QString& name) const
    {
        QSettings s("OpenAI", "BO3HLSLPreviewer");
        const QString stored = s.value("keybinds/" + name).toString();
        if (!stored.isEmpty()) return QKeySequence(stored, QKeySequence::PortableText);
        return shortcutDefaults_.value(name);
    }

    void applyDarkTheme()
    {
        QSettings settings("OpenAI", "BO3HLSLPreviewer");
        currentTheme_ = settings.value("ui/theme", "BO3 Dark").toString();
        applyTheme(currentTheme_);
    }

    void installShortcuts()
    {
        shortcutDefaults_.clear();
        shortcutDefaults_["Open Shader"] = QKeySequence::Open;
        shortcutDefaults_["Save Shader"] = QKeySequence::Save;
        shortcutDefaults_["Compile Shader"] = QKeySequence("Ctrl+Enter");
        shortcutDefaults_["Compile Shader (F5)"] = QKeySequence("F5");
        shortcutDefaults_["Find"] = QKeySequence::Find;
        shortcutDefaults_["Find Next"] = QKeySequence("F3");
        shortcutDefaults_["Find Previous"] = QKeySequence("Shift+F3");
        shortcutDefaults_["Redo"] = QKeySequence("Ctrl+Shift+Z");
        shortcutDefaults_["Close Find"] = QKeySequence("Escape");
        shortcutDefaults_["Toggle Fulbright"] = QKeySequence("Ctrl+Shift+F");
        shortcutDefaults_["Focus Preview"] = QKeySequence("Ctrl+2");
        shortcutDefaults_["Focus Editor"] = QKeySequence("Ctrl+1");
        shortcutDefaults_["Reset Camera"] = QKeySequence("R");

        auto add = [this](const QString& name, std::function<void()> fn)
        {
            auto* s = new QShortcut(shortcutSequence(name), this);
            s->setContext(Qt::ApplicationShortcut);
            shortcuts_[name] = s;
            connect(s, &QShortcut::activated, this, std::move(fn));
        };
        add("Open Shader", [this]{ openShaderDialog(); });
        add("Save Shader", [this]{ saveShader(); });
        add("Compile Shader", [this]{ compileEditor(); });
        add("Compile Shader (F5)", [this]{ compileEditor(); });
        add("Find", [this]{ showFindBar(); });
        add("Find Next", [this]{ findNext(false); });
        add("Find Previous", [this]{ findNext(true); });
        add("Redo", [this]{ editor_->redo(); });
        add("Close Find", [this]{ if (findBar_->isVisible()) closeFindBar(); });
        add("Toggle Fulbright", [this]{
            if (!lightingQuickMode_) return;
            lightingQuickMode_->setCurrentIndex(lightingQuickMode_->currentIndex() == 0 ? 1 : 0);
        });
        add("Focus Preview", [this]{ if (previewDock_) { previewDock_->show(); previewDock_->raise(); preview_->setFocus(); } });
        add("Focus Editor", [this]{ editor_->setFocus(); });
        add("Reset Camera", [this]{ if (preview_) { preview_->renderer().ResetCamera(); updateCameraUi(); } });
    }

    void showBo3LearningGuide(int requestedChapter = -1)
    {
        struct LearningTopic
        {
            QString level;
            QString title;
            QString resource;
        };

        const QVector<LearningTopic> topics = {
            {"Beginner", "Start Here", ":/learning/00_start_here.md"},
            {"Beginner", "HLSL Basics", ":/learning/01_hlsl_basics.md"},
            {"Beginner", "Shader Types", ":/learning/02_shader_types.md"},
            {"Beginner → Intermediate", "BO3 PostFX", ":/learning/03_postfx.md"},
            {"Intermediate", "Techsets 101", ":/learning/04_techsets.md"},
            {"Intermediate", "Textures, Samplers & CodeTextures", ":/learning/05_textures_samplers.md"},
            {"Intermediate", "BO3 Materials", ":/learning/06_materials.md"},
            {"Intermediate", "BO3 Skybox Shaders", ":/learning/07_skybox.md"},
            {"Advanced", "TOOLSGFX vs BO3 Runtime", ":/learning/08_toolsgfx_runtime.md"},
            {"Intermediate → Advanced", "Packaging & Validation", ":/learning/09_packaging_validation.md"},
            {"Advanced", "Debugging BO3 Shaders", ":/learning/10_debugging.md"},
            {"Advanced", "Advanced BO3 HLSL", ":/learning/11_advanced_hlsl.md"},
            {"Beginner → Advanced", "Learning Projects & Glossary", ":/learning/12_learning_projects.md"},
            {"Reference", "Community References & Credits", ":/learning/13_community_resources.md"}
        };

        QDialog dialog(this);
        dialog.setWindowTitle("BO3 HLSL Learning Guide");
        dialog.resize(1180, 760);
        dialog.setMinimumSize(860, 560);

        auto* root = new QVBoxLayout(&dialog);
        root->setContentsMargins(12, 12, 12, 12);
        root->setSpacing(10);

        auto* header = new QLabel(
            "<b style='font-size:16px'>BO3 HLSL Learning Guide</b><br>"
            "<span style='color:#9DA8B5'>Start with shader fundamentals, then move through PostFX, techsets, runtime resources, materials, sky shaders, validation, and advanced debugging.</span>");
        header->setWordWrap(true);
        root->addWidget(header);

        auto* pathLabel = new QLabel("Learning path:  BEGINNER  →  INTERMEDIATE  →  ADVANCED");
        pathLabel->setObjectName("SectionHeader");
        root->addWidget(pathLabel);

        auto* splitter = new QSplitter(Qt::Horizontal);
        splitter->setChildrenCollapsible(false);
        root->addWidget(splitter, 1);

        auto* navigation = new QWidget();
        auto* navLayout = new QVBoxLayout(navigation);
        navLayout->setContentsMargins(0, 0, 4, 0);
        navLayout->setSpacing(6);
        auto* filter = new QLineEdit();
        filter->setPlaceholderText("Filter topics...");
        navLayout->addWidget(filter);
        auto* topicList = new QListWidget();
        topicList->setAlternatingRowColors(false);
        topicList->setMinimumWidth(275);
        for(const LearningTopic& topic : topics)
        {
            auto* item = new QListWidgetItem(QString("%1  ·  %2").arg(topic.level, topic.title));
            item->setData(Qt::UserRole, topic.resource);
            item->setData(Qt::UserRole + 1, topic.title);
            item->setToolTip(topic.level + " — " + topic.title);
            topicList->addItem(item);
        }
        navLayout->addWidget(topicList, 1);
        splitter->addWidget(navigation);

        auto* documentPanel = new QWidget();
        auto* documentLayout = new QVBoxLayout(documentPanel);
        documentLayout->setContentsMargins(4, 0, 0, 0);
        documentLayout->setSpacing(6);
        auto* browser = new QTextBrowser();
        browser->setOpenExternalLinks(true);
        browser->setReadOnly(true);
        browser->setTextInteractionFlags(Qt::TextBrowserInteraction | Qt::TextSelectableByKeyboard);
        browser->document()->setDefaultStyleSheet(R"CSS(
            body { color:#E3E8EF; background:#0D1014; font-family:'Segoe UI'; line-height:1.45; }
            h1 { color:#FFFFFF; margin-top:4px; margin-bottom:12px; }
            h2 { color:#9CCAF2; margin-top:22px; margin-bottom:8px; }
            h3 { color:#B8D7F0; margin-top:16px; }
            p, li { font-size:10.5pt; }
            code { font-family:Consolas, monospace; background:#171B21; color:#D7E8F7; }
            pre { background:#090C10; border:1px solid #353D49; padding:10px; }
            blockquote { color:#DCDCAA; border-left:3px solid #4D8FCC; margin-left:4px; padding-left:10px; }
            a { color:#68A9E0; }
        )CSS");
        documentLayout->addWidget(browser, 1);

        auto* findRow = new QHBoxLayout();
        auto* findInPage = new QLineEdit();
        findInPage->setPlaceholderText("Find in this chapter...");
        auto* findPrevious = new QPushButton("Previous");
        auto* findNext = new QPushButton("Next");
        findRow->addWidget(findInPage, 1);
        findRow->addWidget(findPrevious);
        findRow->addWidget(findNext);
        documentLayout->addLayout(findRow);
        splitter->addWidget(documentPanel);
        splitter->setSizes({300, 840});

        auto loadTopic = [browser, topicList](int row)
        {
            if(row < 0 || row >= topicList->count()) return;
            QListWidgetItem* item = topicList->item(row);
            const QString resource = item->data(Qt::UserRole).toString();
            QFile file(resource);
            if(!file.open(QIODevice::ReadOnly | QIODevice::Text))
            {
                browser->setHtml("<h1>Documentation unavailable</h1><p>The embedded chapter could not be opened.</p>");
                return;
            }
            browser->setMarkdown(QString::fromUtf8(file.readAll()));
            browser->verticalScrollBar()->setValue(0);
            QSettings settings("OpenAI", "BO3HLSLPreviewer");
            settings.setValue("docs/lastLearningTopic", resource);
        };

        connect(topicList, &QListWidget::currentRowChanged, &dialog, loadTopic);
        connect(filter, &QLineEdit::textChanged, &dialog, [topicList](const QString& text)
        {
            for(int i = 0; i < topicList->count(); ++i)
                topicList->item(i)->setHidden(!topicList->item(i)->text().contains(text, Qt::CaseInsensitive));
        });
        connect(findInPage, &QLineEdit::returnPressed, &dialog, [browser, findInPage]
        {
            if(findInPage->text().isEmpty()) return;
            if(!browser->find(findInPage->text()))
            {
                QTextCursor cursor = browser->textCursor();
                cursor.movePosition(QTextCursor::Start);
                browser->setTextCursor(cursor);
                browser->find(findInPage->text());
            }
        });
        connect(findNext, &QPushButton::clicked, &dialog, [browser, findInPage]
        {
            if(findInPage->text().isEmpty()) return;
            if(!browser->find(findInPage->text()))
            {
                QTextCursor cursor = browser->textCursor();
                cursor.movePosition(QTextCursor::Start);
                browser->setTextCursor(cursor);
                browser->find(findInPage->text());
            }
        });
        connect(findPrevious, &QPushButton::clicked, &dialog, [browser, findInPage]
        {
            if(findInPage->text().isEmpty()) return;
            if(!browser->find(findInPage->text(), QTextDocument::FindBackward))
            {
                QTextCursor cursor = browser->textCursor();
                cursor.movePosition(QTextCursor::End);
                browser->setTextCursor(cursor);
                browser->find(findInPage->text(), QTextDocument::FindBackward);
            }
        });

        auto* footer = new QHBoxLayout();
        auto* openPostFx = new QPushButton("Open PostFX Starter");
        auto* openMaterial = new QPushButton("Open Material Starter");
        auto* openSky = new QPushButton("Open Skybox Starter");
        auto* openGeneric = new QPushButton("Open Generic HLSL Starter");
        auto* closeButton = new QPushButton("Close");
        footer->addWidget(openPostFx);
        footer->addWidget(openMaterial);
        footer->addWidget(openSky);
        footer->addWidget(openGeneric);
        footer->addStretch(1);
        footer->addWidget(closeButton);
        root->addLayout(footer);

        connect(closeButton, &QPushButton::clicked, &dialog, &QDialog::accept);
        connect(openPostFx, &QPushButton::clicked, &dialog, [this, &dialog]{ dialog.accept(); openBundledExample("sample_bo3_postfx.hlsl"); });
        connect(openMaterial, &QPushButton::clicked, &dialog, [this, &dialog]{ dialog.accept(); openBundledExample("sample_bo3_material.hlsl"); });
        connect(openSky, &QPushButton::clicked, &dialog, [this, &dialog]{ dialog.accept(); openBundledExample("sample_bo3_skybox.hlsl"); });
        connect(openGeneric, &QPushButton::clicked, &dialog, [this, &dialog]{ dialog.accept(); openBundledExample("sample_generic_hlsl.hlsl"); });

        const int topicCount = static_cast<int>(topics.size());
        int initialRow = std::clamp(requestedChapter, 0, topicCount - 1);
        if(requestedChapter < 0)
        {
            QSettings settings("OpenAI", "BO3HLSLPreviewer");
            const QString last = settings.value("docs/lastLearningTopic").toString();
            for(int i = 0; i < topicCount; ++i)
            {
                if(topics[i].resource == last)
                {
                    initialRow = i;
                    break;
                }
            }
        }
        topicList->setCurrentRow(initialRow);
        dialog.exec();
    }

    void openBundledExample(const QString& fileName)
    {
        if(!maybeSave()) return;
        fs::path sample = GetExecutableDirectory() / L"shaders" / fileName.toStdWString();
        if(!fs::exists(sample))
            sample = fs::current_path() / L"shaders" / fileName.toStdWString();
        if(!fs::exists(sample))
        {
            QMessageBox::warning(this, "Bundled shader example",
                "Could not find shaders/" + fileName + " in the application folder.");
            return;
        }
        openShader(QString::fromStdWString(sample.wstring()));
    }

    void openBundledSample()
    {
        // Startup uses the authored PostFX example. openShader() now performs the
        // same mode detection used for every other shader, so the sample does not
        // need a special forced Preview As path.
        const fs::path bundled = GetExecutableDirectory() / L"shaders" / L"sample_bo3_postfx.hlsl";
        if (fs::exists(bundled)) openShader(QString::fromStdWString(bundled.wstring()));
        else
        {
            const fs::path sourceTree = fs::current_path() / L"shaders" / L"sample_bo3_postfx.hlsl";
            if (fs::exists(sourceTree)) openShader(QString::fromStdWString(sourceTree.wstring()));
        }
    }

    bool maybeSave()
    {
        if (!modified_) return true;
        const auto answer = QMessageBox::question(this, "Unsaved shader", "Save changes to the current shader?", QMessageBox::Save | QMessageBox::Discard | QMessageBox::Cancel);
        if (answer == QMessageBox::Cancel) return false;
        if (answer == QMessageBox::Save) return saveShader();
        return true;
    }

    void openShaderDialog()
    {
        if (!maybeSave()) return;
        const QString path = QFileDialog::getOpenFileName(this, "Open HLSL shader", currentDirectory(), "HLSL shaders (*.hlsl *.hlsli *.h);;All files (*.*)");
        if (!path.isEmpty()) openShader(path);
    }

    void openShader(const QString& path, bool preserveEditorView = false)
    {
        QFile file(path);
        if (!file.open(QIODevice::ReadOnly))
        {
            QMessageBox::warning(this, "Open failed", "Could not open:\n" + path);
            return;
        }
        const CodeEditor::ViewState previousView = editor_->captureViewState();
        loadingText_ = true;
        editor_->setPlainText(QString::fromUtf8(file.readAll()));
        editor_->document()->setModified(false);
        loadingText_ = false;
        shaderPath_ = QFileInfo(path).absoluteFilePath();
        // Temporary Preview As state belongs only to the shader that produced
        // it. Never let its mappings, stages, or generated techset cross a load.
        previewPackageSession_.clear();
        temporaryPreviewMappings_.clear();
        temporaryPreviewValidationPassed_ = false;
        updateTemporaryPreviewActions();
        loadCompanionTechset(shaderPath_);
        modified_ = false;
        preview_->renderer().ResetScriptVectorOverrides();
        preview_->renderer().ResetCamera();
        cameraUserOverride_ = false;
        const QString loadedShaderText = editor_->toPlainText();
        const PreviewModeDetection detection = detectPreviewMode(loadedShaderText);
        setDetectedPreviewMode(detection, true);
        if(detection.mode == PreviewMode::ForwardMaterial || detection.mode == PreviewMode::DeferredGBuffer)
        {
            if(meshCombo_)
            {
                // Sphere is the neutral/default material inspection mesh for every
                // material type. Card remains available as an explicit choice for
                // foliage/cutout testing, but loading a material must not silently
                // switch away from the default sphere.
                meshCombo_->setCurrentIndex(static_cast<int>(PreviewMesh::Sphere));
            }
            if(camera3D_) camera3D_->setChecked(true);
        }
        else if(detection.mode == PreviewMode::Sky)
        {
            if(camera3D_) camera3D_->setChecked(true);
        }
        else
        {
            if(camera3D_) camera3D_->setChecked(false);
        }
        updateGBufferUi();
        updateCameraUi();
        lastWriteTimeValid_ = readLastWriteTime();
        if(preserveEditorView) editor_->restoreViewState(previousView);
        else editor_->moveCursor(QTextCursor::Start);
        updateTitle();
        compileEditor();
        statusBar()->showMessage("Opened " + QFileInfo(path).fileName(), 3000);
    }

    bool saveShader()
    {
        QString target = shaderPath_;
        if (target.isEmpty())
            target = QFileDialog::getSaveFileName(this, "Save HLSL shader", currentDirectory() + "/shader.hlsl", "HLSL shaders (*.hlsl);;All files (*.*)");
        if (target.isEmpty()) return false;
        QFile file(target);
        if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate))
        {
            QMessageBox::warning(this, "Save failed", "Could not save:\n" + target);
            return false;
        }
        file.write(editor_->toPlainText().toUtf8());
        shaderPath_ = QFileInfo(target).absoluteFilePath();
        loadCompanionTechset(shaderPath_);
        modified_ = false;
        editor_->document()->setModified(false);
        lastWriteTimeValid_ = readLastWriteTime();
        updateTitle();
        statusBar()->showMessage("Saved " + QFileInfo(target).fileName(), 2500);
        return true;
    }

    bool saveShaderAs()
    {
        QString target = QFileDialog::getSaveFileName(
            this, "Save HLSL shader as", shaderPath_.isEmpty()
                ? currentDirectory() + "/shader.hlsl" : shaderPath_,
            "HLSL shaders (*.hlsl);;All files (*.*)");
        if(target.isEmpty()) return false;
        if(!target.endsWith(".hlsl", Qt::CaseInsensitive)) target += ".hlsl";

        const QString previousShader = shaderPath_;
        const QString previousTechset = techsetPath_;
        const QString previousTechsetSource = techsetSource_;
        bool updateTechset = false;
        if(!previousTechset.isEmpty())
        {
            const auto answer = QMessageBox::question(
                this, "Update Associated Techset",
                QString("This shader is associated with %1 (%2).\n\nCreate a renamed same-basename techset and update its source field to %3?")
                    .arg(QFileInfo(previousTechset).fileName(), bo3::toString(techsetOrigin_),
                         QFileInfo(target).fileName()),
                QMessageBox::Yes | QMessageBox::No | QMessageBox::Cancel);
            if(answer == QMessageBox::Cancel) return false;
            updateTechset = answer == QMessageBox::Yes;
        }

        QFile shaderFile(target);
        if(!shaderFile.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text))
        {
            QMessageBox::warning(this, "Save As", "Could not write:\n" + target);
            return false;
        }
        shaderFile.write(editor_->toPlainText().toUtf8());
        shaderFile.close();

        if(updateTechset)
        {
            QString updated = previousTechsetSource;
            const QString oldName = QFileInfo(previousShader).fileName();
            const QString newName = QFileInfo(target).fileName();
            updated.replace(QString("\"%1\"").arg(oldName), QString("\"%1\"").arg(newName));
            const QString newTechset = QFileInfo(target).dir().filePath(
                QFileInfo(target).completeBaseName() + ".techsetdef");
            QFile techsetFile(newTechset);
            if(!techsetFile.open(QIODevice::WriteOnly | QIODevice::Truncate | QIODevice::Text))
            {
                QMessageBox::warning(this, "Save As",
                    "The shader copy was saved, but its renamed techset could not be written:\n" + newTechset);
                return false;
            }
            techsetFile.write(updated.toUtf8());
        }

        openShader(QFileInfo(target).absoluteFilePath(), true);
        statusBar()->showMessage(updateTechset
            ? "Saved shader and updated same-basename techset association"
            : "Saved shader copy; package association was rediscovered by basename", 4000);
        return true;
    }

    void reloadShader()
    {
        if (shaderPath_.isEmpty()) return;
        if (modified_ && QMessageBox::question(this, "Reload shader", "Discard editor changes and reload the file from disk?") != QMessageBox::Yes) return;
        openShader(shaderPath_, true);
    }

    void compileEditor()
    {
        setCompileStatusBadge("Compiling...", "#DCDCAA");
        QString initError;
        if (!preview_->ensureInitialized(initError))
        {
            setCompilerOutput("DirectX preview initialization failed:\n" + initError, OutputKind::Error);
            setCompileStatusBadge(QString::fromUtf8("✕ HLSL FAIL"), "#FF7070");
            return;
        }
        const QString originalSource = editor_->toPlainText();
        const fs::path nativePath = shaderPath_.isEmpty() ? fs::path() : fs::path(shaderPath_.toStdWString());
        const fs::path nativeRoot = includeRoot_.isEmpty() ? fs::path() : fs::path(includeRoot_.toStdWString());
        const PreviewMode activeMode = selectedPreviewMode();
        const bool genericHlslMode = activeMode == PreviewMode::HLSL;
        const bool strictPackageMode = !genericHlslMode;
        const bo3::PackageConfiguration configuration = selectedPackageConfiguration(activeMode);
        // An adjacent/imported techset is authoritative only for the shader type
        // it was actually detected with. Advanced Preview As overrides must build
        // a fresh temporary package instead of accidentally validating a PostFX
        // techset while the UI says Material/Skybox (or vice versa).
        const bool physicalPackageMatchesTarget = !detectedPreviewModeValid_ ||
            activeMode == detectedPreviewMode_;
        const bool hasPhysicalPackage = strictPackageMode &&
            !techsetSource_.trimmed().isEmpty() && physicalPackageMatchesTarget;

        const bo3::PreviewPackageState* temporaryState = nullptr;
        QString previewSource = originalSource;
        temporaryPreviewValidationPassed_ = false;
        if(!hasPhysicalPackage)
        {
            temporaryState = &rebuildTemporaryPreviewPackage(
                originalSource, activeMode, configuration);
            if(temporaryState->readyForPreviewCompilation)
                previewSource = temporaryState->adaptedSource;
        }
        else
        {
            // An authored/imported/same-basename persistent package is
            // authoritative in strict modes. Temporary state must not shadow it.
            previewPackageSession_.clear();
        }

        preview_->renderer().ClearPreviewResourceMappings();
        if(strictPackageMode && temporaryState)
            preview_->renderer().SetPreviewResourceMappings(temporaryState->adapter.mappings);
        updateTemporaryPreviewActions();

        const QByteArray previewBytes = previewSource.toUtf8();
        const std::string source(previewBytes.constData(), static_cast<size_t>(previewBytes.size()));
        const bool allowSyntheticGlobals = genericHlslMode && bo3Globals_->isChecked();
        QString previewEntry = genericHlslMode
            ? entry_->text().trimmed() : QString("ps_main");
        QString previewProfile = genericHlslMode
            ? profile_->text().trimmed() : QString("ps_5_0");
        if(strictPackageMode && temporaryState &&
           temporaryState->confidence == bo3::AutomationConfidence::Auto)
        {
            const bo3::TechniqueResolutionResult resolved = bo3::resolveTechnique(
                temporaryState->adapter.techset,
                temporaryState->adapter.selectedTechnique);
            if(resolved.found && !resolved.technique.pixelShader.entryPoint.isEmpty())
                previewEntry = resolved.technique.pixelShader.entryPoint;
        }
        else if(hasPhysicalPackage)
        {
            bo3::TechsetParseOptions options;
            options.configuration = configuration;
            const bo3::TechsetParseResult parsed = bo3::parseTechset(
                techsetSource_, techsetPath_.isEmpty() ? "companion.techsetdef" : techsetPath_, options);
            const QString technique = selectedTechniqueForTechset(
                techsetSource_, configuration);
            const bo3::TechniqueResolutionResult resolved = bo3::resolveTechnique(
                parsed.model, technique);
            if(resolved.found && !resolved.technique.pixelShader.entryPoint.isEmpty())
                previewEntry = resolved.technique.pixelShader.entryPoint;
        }
        std::wstring output;
        const bool ok = preview_->renderer().CompilePixelShader(source, nativePath, nativeRoot,
            previewEntry.toStdString(), previewProfile.toStdString(), allowSyntheticGlobals, output);
        output = DeduplicateCompilerDiagnostics(output);
        QString text = ToQString(output);
        if (ok)
        {
            setCompileStatusBadge(QString::fromUtf8("✓ HLSL PASS"), "#76D49B");
            // The adapter starts from source declarations, but BO3 binds the
            // optimized shader interface. Prune temporary PostFX resources that
            // FXC removed before validating/serializing the generated techset.
            // This prevents phantom bindings such as an unused frameBuffer from
            // turning an otherwise valid Runtime package into
            // PACKAGE_BINDING_OPTIMIZED_OUT.
            if(strictPackageMode && temporaryState &&
               activeMode == PreviewMode::PostFX &&
               temporaryState->confidence == bo3::AutomationConfidence::Auto &&
               preview_->renderer().OptimizedPixelResourceReflectionValid() &&
               previewPackageSession_.pruneOptimizedOutPostFxResources(
                   preview_->renderer().OptimizedPixelResourceNames()))
            {
                temporaryState = &previewPackageSession_.state();
                preview_->renderer().ClearPreviewResourceMappings();
                preview_->renderer().SetPreviewResourceMappings(
                    temporaryState->adapter.mappings);
                updateTemporaryPreviewActions();
            }

            if (text.trimmed().isEmpty()) text = "[Preview] Compile succeeded.";
            else if (text.contains("warning X", Qt::CaseInsensitive)) text = "[Preview] Compile succeeded. Warnings do not stop rendering.\n\n" + text;

            bo3::ValidationResult packageValidation;
            bo3::CompatibilityStatus packageStatus = bo3::CompatibilityStatus::Unknown;
            bool hasPackageValidation = false;
            bool suppressPackagePreview = strictPackageMode;
            bool packageMetadataStale = false;
            QString packageDescription;
            QString generationStatus;
            const bool authoredPackage = hasPhysicalPackage &&
                !preview_->renderer().IsVertexOnlyShader();
            if(authoredPackage)
            {
                generationStatus = "N/A (AUTHORED TECHSET)";
                const QString packageSource = originalSource;
                // Refresh an adjacent authored/generated techset on every compile
                // so the selected package can never be a stale copy from another
                // shader. HLSL mode deliberately never enters this path.
                QFile companion(techsetPath_);
                if(companion.open(QIODevice::ReadOnly | QIODevice::Text))
                    techsetSource_ = QString::fromUtf8(companion.readAll());
                const QString techset = techsetSource_;
                const QString logicalPath = shaderPath_.isEmpty() ? "preview_shader.hlsl"
                                                                  : QFileInfo(shaderPath_).fileName();
                const QString selectedTechnique = selectedTechniqueForTechset(techset, configuration);
                packageDescription = QString("Techset: %1\nTechset Origin: %2\nTechnique: %3\nConfiguration: %4")
                    .arg(QFileInfo(techsetPath_).fileName(), bo3::toString(techsetOrigin_), selectedTechnique,
                         bo3::toString(configuration));
                const bo3::PackageTarget target = activeMode == PreviewMode::PostFX
                    ? bo3::PackageTarget::PostFx
                    : (activeMode == PreviewMode::Sky ? bo3::PackageTarget::Skybox
                                                      : bo3::PackageTarget::Material);
                const QString currentFingerprint = bo3::shaderInterfaceFingerprint(
                    bo3::analyzeShaderSource(packageSource), target);
                packageMetadataStale = bo3::isAutoTechsetStale(techset, currentFingerprint);
                if(packageMetadataStale)
                {
                    packageDescription += "\nPackage interface changed: auto-generated techset review/update is required.";
                }
                else
                {
                    hasPackageValidation = true;
                    if(activeMode == PreviewMode::PostFX)
                        packageValidation.append(validatePostFxPackageForBo3(
                            packageSource, techset, logicalPath, configuration, selectedTechnique));
                    else
                        packageValidation.append(validateGeneratedPackageForBo3(
                            packageSource, techset, logicalPath, selectedTechnique, configuration));
                    packageStatus = packageValidation.status();
                    suppressPackagePreview = packageStatus == bo3::CompatibilityStatus::Fail ||
                                             packageStatus == bo3::CompatibilityStatus::Unknown;
                }
            }
            else if(strictPackageMode && temporaryState)
            {
                packageDescription = QString(
                    "Preview Target: %1\nAdapter: %2\nTechset: AUTO (temporary)\nConfiguration: %3\nPixel Entry: %4\nSession Generation: %5\nSession Fingerprint: %6")
                    .arg(bo3::toString(temporaryState->target),
                         bo3::toString(temporaryState->confidence),
                         bo3::toString(configuration), previewEntry)
                    .arg(temporaryState->generation)
                    .arg(temporaryState->stateFingerprint.left(16));

                if(temporaryState->confidence == bo3::AutomationConfidence::Auto &&
                   !temporaryState->temporaryTechsetText.trimmed().isEmpty())
                {
                    hasPackageValidation = true;
                    generationStatus = "PASS (AUTO, IN MEMORY)";
                    if(activeMode == PreviewMode::PostFX)
                        packageValidation.append(validatePostFxPackageForBo3(
                            temporaryState->adaptedSource,
                            temporaryState->temporaryTechsetText,
                            temporaryState->sourceFileName,
                            configuration,
                            temporaryState->adapter.selectedTechnique));
                    else
                        packageValidation.append(validateGeneratedPackageForBo3(
                            temporaryState->adaptedSource,
                            temporaryState->temporaryTechsetText,
                            temporaryState->sourceFileName,
                            temporaryState->adapter.selectedTechnique,
                            configuration));
                    packageStatus = packageValidation.status();
                    suppressPackagePreview = packageStatus == bo3::CompatibilityStatus::Fail ||
                                             packageStatus == bo3::CompatibilityStatus::Unknown;
                    // WARNING is still a validated, previewable package: only
                    // FAIL/UNKNOWN are suppressed. Allow users to persist the
                    // exact live package they are already seeing when validation
                    // found non-fatal warnings (for example an optimized-out
                    // unused top-level parameter).
                    temporaryPreviewValidationPassed_ =
                        packageStatus == bo3::CompatibilityStatus::Pass ||
                        packageStatus == bo3::CompatibilityStatus::Warning;
                }
                else if(temporaryState->confidence == bo3::AutomationConfidence::Guided)
                {
                    generationStatus = "GUIDED — REVIEW REQUIRED";
                    packageDescription += "\nThe adapter needs explicit resource mappings before a BO3 package can be validated.";
                }
                else
                {
                    generationStatus = "UNSUPPORTED";
                    packageDescription += "\nThe selected target cannot be adapted without changing unproven shader semantics.";
                }
            }
            preview_->renderer().SetPackagePreviewSuppressed(suppressPackagePreview);
            updateTemporaryPreviewActions();

            if(genericHlslMode)
            {
                text = "HLSL Compile: PASS\n"
                       "Preview Adapter: Generic HLSL\n"
                       "Techset: AUTO (temporary compatibility harness)\n"
                       "BO3 Package Validation: N/A\n"
                       "Preview: AVAILABLE\n\n"
                       "HLSL Preview — Generic Direct3D shader preview. Rendering here does not prove BO3 package compatibility.\n"
                       "Missing gameTime/renderTargetSize convenience values may be supplied as synthetic Previewer inputs.\n\n" + text;
            }
            else if(hasPackageValidation)
            {
                text = QString("HLSL Compile: PASS\nPackage Generation: %1\nBO3 Package Validation: %2\nPreview: %3\n\n%4")
                    .arg(generationStatus.isEmpty() ? "PASS" : generationStatus)
                    .arg(bo3::toString(packageStatus), suppressPackagePreview ? "SUPPRESSED" : "AVAILABLE",
                         packageDescription + "\n\n" + text);
                if(!packageValidation.diagnostics.isEmpty())
                    text += "\n\n" + packageValidation.toText();
                if(temporaryState &&
                   !temporaryState->adapter.diagnostics.diagnostics.isEmpty())
                    text += "\n\nAdapter diagnostics:\n" +
                            temporaryState->adapter.diagnostics.toText();
            }
            else
            {
                QString packageGuidance;
                if(packageMetadataStale)
                    packageGuidance = packageDescription +
                        "\nUse Package Shader As... to review mappings and generate a refreshed protected package.";
                else if(temporaryState)
                {
                    packageGuidance = packageDescription;
                    if(!temporaryState->adapter.diagnostics.diagnostics.isEmpty())
                        packageGuidance += "\n\n" + temporaryState->adapter.diagnostics.toText();
                    if(temporaryState->hasGuidedMappings())
                        packageGuidance += "\n\nUse Package / Save > Review Preview Mappings to resolve this live session.";
                }
                else
                    packageGuidance = "No valid package is available for this strict preview target.";
                text = QString("HLSL Compile: PASS\n"
                               "Package Generation: %1\n"
                               "BO3 Package Validation: NOT RUN\n"
                               "Preview: SUPPRESSED IN %2 MODE\n\n"
                               "%3\n\n%4")
                           .arg(packageMetadataStale ? "STALE — REVIEW REQUIRED" :
                                (generationStatus.isEmpty() ? "NEEDS INPUT" : generationStatus))
                           .arg(activeMode == PreviewMode::PostFX ? "POSTFX" :
                                (activeMode == PreviewMode::Sky ? "SKYBOX" : "MATERIAL"))
                           .arg(packageGuidance, text);
            }

            if(preview_->renderer().IsLiveCaptureSource())
            {
                text += "\n\nSource: LIVE BO3 WINDOW — LDR APPROX\n"
                        "External Windows Graphics Capture supplies the composited display image. "
                        "In BO3 Runtime mode this is approximate reconstruction, not raw resolvedScene HDR.";
            }

            const std::vector<int> missingChannels = preview_->renderer().MissingShadertoyChannels();
            if (!missingChannels.empty())
            {
                QStringList names;
                for (const int channel : missingChannels) names << QString("iChannel%1").arg(channel);
                text += QString("\n\n[Preview] REQUIRED SHADER INPUTS MISSING: %1\n"
                                "The GLSL references these external Shadertoy textures, but no image is loaded for them. "
                                "The shader can compile while rendering blank or completely wrong.\n"
                                "Open Shader Inputs (or View > Material Textures) and load the exact images shown under Shader Inputs on Shadertoy.")
                            .arg(names.join(", "));
            }
            const QString bo3CompatibilityIssue = bo3RuntimeCompatibilityIssue(editor_->toPlainText());
            if (!bo3CompatibilityIssue.isEmpty())
            {
                text += QString("\n\n[BO3 Compatibility] PREVIEW-ONLY TEMPORAL FEEDBACK\n%1\n\n"
                                "DirectX preview result != current BO3 runtime support. Export is blocked until a BO3 persistent-history binding is implemented.")
                            .arg(bo3CompatibilityIssue);
            }
            const bool hasWarnings = text.contains("warning X", Qt::CaseInsensitive) ||
                                     !missingChannels.empty() || !bo3CompatibilityIssue.isEmpty() ||
                                     (strictPackageMode && (!hasPackageValidation || packageStatus != bo3::CompatibilityStatus::Pass));
            const bool adapterUnsupported = strictPackageMode && temporaryState &&
                temporaryState->confidence == bo3::AutomationConfidence::Unsupported;

            // Once strict-package validation is known, the toolbar badge summarizes
            // both stages instead of showing only the earlier FXC result. Generic
            // HLSL mode intentionally remains HLSL-only because BO3 validation is N/A.
            if(genericHlslMode)
            {
                setCompileStatusBadge(QString::fromUtf8("✓ HLSL"), "#76D49B");
            }
            else if(hasPackageValidation)
            {
                if(packageStatus == bo3::CompatibilityStatus::Pass)
                    setCompileStatusBadge(QString::fromUtf8("✓ HLSL · ✓ BO3"), "#76D49B");
                else if(packageStatus == bo3::CompatibilityStatus::Warning)
                    setCompileStatusBadge(QString::fromUtf8("✓ HLSL · ! BO3"), "#DCDCAA");
                else if(packageStatus == bo3::CompatibilityStatus::Fail)
                    setCompileStatusBadge(QString::fromUtf8("✓ HLSL · ✕ BO3"), "#FF7070");
                else
                    setCompileStatusBadge(QString::fromUtf8("✓ HLSL · BO3 ?"), "#DCDCAA");
            }
            else
            {
                setCompileStatusBadge(QString::fromUtf8("✓ HLSL · BO3 —"), "#DCDCAA");
            }

            const OutputKind outputKind = (hasPackageValidation && packageStatus == bo3::CompatibilityStatus::Fail) ||
                                          adapterUnsupported
                ? OutputKind::Error : (hasWarnings ? OutputKind::Warning : OutputKind::Success);
            setCompilerOutput(text, outputKind);
            refreshScriptVectorControls();
            refreshShaderParameterControls();
            refreshSourceValueControls();
            refreshShadertoyChannelUi();
            if (!missingChannels.empty() && materialDock_)
            {
                materialDock_->show();
                materialDock_->raise();
            }
            if (preview_->renderer().IsVertexOnlyShader())
            {
                QSignalBlocker blocker(previewModeCombo_);
                const int modeIndex = previewModeCombo_->findData(
                    static_cast<int>(preview_->renderer().GetPreviewMode()));
                if(modeIndex >= 0) previewModeCombo_->setCurrentIndex(modeIndex);
            }
            syncCameraModeFromShader();
            updateGBufferUi();
            updatePerformanceUi();
            if (preview_->renderer().IsVertexOnlyShader())
                statusBar()->showMessage("Vertex displacement shader compiled - vs_5_0 material preview enabled", 3500);
            else if(suppressPackagePreview)
                statusBar()->showMessage(QString("HLSL compiled; BO3 package %1; preview suppressed")
                                             .arg(generationStatus.isEmpty()
                                                 ? bo3::toString(packageStatus) : generationStatus), 5000);
            else if (!bo3CompatibilityIssue.isEmpty())
                statusBar()->showMessage("Shader previews correctly, but current BO3 export/runtime does not support its temporal history resource", 5000);
            else if(genericHlslMode)
                statusBar()->showMessage("Generic HLSL preview available; BO3 package validation is N/A", 5000);
            else if(!hasPackageValidation)
                statusBar()->showMessage("HLSL compiled; strict package preview suppressed until a techset is generated or selected", 5000);
            else
                statusBar()->showMessage(preview_->renderer().IsSkyShaderMode() ? "Shader compiled - 3D sky navigation enabled" : "Shader compiled successfully", 2500);
        }
        else
        {
            setCompileStatusBadge(QString::fromUtf8("✕ HLSL FAIL"), "#FF7070");
            // Never leave the previously compiled image visible after a failed
            // target/source transition; it would be stale preview state.
            preview_->renderer().SetPackagePreviewSuppressed(true);
            temporaryPreviewValidationPassed_ = false;
            updateTemporaryPreviewActions();
            QString failure = text.isEmpty() ? "Compile failed." : text;
            if(strictPackageMode && temporaryState &&
               !temporaryState->adapter.diagnostics.diagnostics.isEmpty())
                failure += "\n\n" + temporaryState->adapter.diagnostics.toText();
            setCompilerOutput(failure, OutputKind::Error);
            statusBar()->showMessage("Shader compile failed", 3500);
        }
    }

    void setCompileStatusBadge(const QString& text, const QString& color)
    {
        if(!compileStatusBadge_) return;
        compileStatusBadge_->setText(text);
        QString background = "rgba(60, 68, 78, 120)";
        QString border = "rgba(100, 112, 126, 180)";
        if(color.compare("#76D49B", Qt::CaseInsensitive) == 0)
        {
            background = "rgba(38, 92, 58, 135)";
            border = "rgba(72, 150, 94, 190)";
        }
        else if(color.compare("#FF7070", Qt::CaseInsensitive) == 0)
        {
            background = "rgba(110, 42, 42, 135)";
            border = "rgba(190, 76, 76, 190)";
        }
        else if(color.compare("#DCDCAA", Qt::CaseInsensitive) == 0)
        {
            background = "rgba(96, 88, 42, 120)";
            border = "rgba(165, 151, 74, 180)";
        }
        compileStatusBadge_->setStyleSheet(QString(
            "QLabel#CompileStatusBadge { color:%1; background:%2; border:1px solid %3; border-radius:11px; padding:4px 10px; font-weight:600; }")
            .arg(color, background, border));
    }

    enum class OutputKind { Normal, Success, Warning, Error };
    void setCompilerOutput(const QString& text, OutputKind kind)
    {
        // Keep an untruncated copy separate from QPlainTextEdit. The widget may
        // enforce a block limit for very large corpus reports, but Copy All must
        // always copy the complete report that was generated. Strip embedded NULs
        // first: FXC error blobs include them and Windows/Qt clipboard display paths
        // can treat the first NUL as end-of-text even though QString still has data.
        QString safeText = text;
        safeText.remove(QChar('\0'));
        compilerOutputFullText_ = safeText;
        QString color = "#D4D4D4";
        if (kind == OutputKind::Success) color = "#76D49B";
        else if (kind == OutputKind::Warning) color = "#E6BE55";
        else if (kind == OutputKind::Error) color = "#FF7070";
        compilerOutput_->setStyleSheet(QString("QPlainTextEdit { background:#0F1013; border:1px solid #343941; color:%1; }").arg(color));
        compilerOutput_->setPlainText(safeText);
        compilerOutput_->moveCursor(QTextCursor::Start);
    }

    void refreshPostFxRuntimeUi()
    {
        if (!postFxRuntimeSourceLabel_ || !postFxRuntimeExposureEv_) return;
        const bool postFx = previewModeCombo_ && selectedPreviewMode() == PreviewMode::PostFX;
        const bool runtime = postFxContextCombo_ &&
            postFxContextCombo_->currentData().toInt() == static_cast<int>(PostFxPreviewContext::Bo3RuntimeResolvedScene);
        const bool enabled = postFx && runtime;

        const bool live = preview_ && preview_->renderer().IsLiveCaptureSource();
        const bool liveActive = preview_ && preview_->renderer().LiveCaptureActive();
        const bool capturePreviewMode = selectedPreviewMode() == PreviewMode::HLSL ||
            selectedPreviewMode() == PreviewMode::PostFX;
        const bool hdr = preview_ && preview_->renderer().SourceIsLinearHDR();
        postFxRuntimeSourceLabel_->setText(live ? "LIVE LDR APPROX" : (hdr ? "HDR linear" : "LDR approx"));
        postFxRuntimeSourceLabel_->setStyleSheet(hdr && !live
            ? "QLabel { color:#76D49B; font-weight:600; }"
            : "QLabel { color:#E6BE55; font-weight:600; }");
        postFxRuntimeSourceLabel_->setEnabled(enabled || live);
        postFxRuntimeExposureEv_->setEnabled(enabled);
        if(postFxResetExposureButton_) postFxResetExposureButton_->setEnabled(enabled);

        // Keep the Live Capture section useful before a capture has started.
        // Previously every child was hidden until IsLiveCaptureSource() became
        // true, leaving an empty group box with no way to discover/select a
        // window from the inspector itself.
        if(liveCaptureStatusLabel_)
        {
            if(!capturePreviewMode)
                liveCaptureStatusLabel_->setText("Available in HLSL and PostFX preview modes.");
            else if(liveActive)
                liveCaptureStatusLabel_->setText("Capturing a window (LDR approximation).");
            else
                liveCaptureStatusLabel_->setText("Not capturing");
        }
        if(selectCaptureWindowButton_)
        {
            selectCaptureWindowButton_->setVisible(true);
            selectCaptureWindowButton_->setEnabled(capturePreviewMode);
            selectCaptureWindowButton_->setText(liveActive ? "Change Window..." : "Select Window...");
        }
        if(stopCaptureButton_)
        {
            stopCaptureButton_->setVisible(liveActive);
            stopCaptureButton_->setEnabled(liveActive);
        }
        if(liveComparisonCombo_) liveComparisonCombo_->setVisible(liveActive);
        if(liveSplitSlider_) liveSplitSlider_->setVisible(
            liveActive && liveComparisonCombo_ &&
            liveComparisonCombo_->currentData().toInt() == static_cast<int>(LiveComparisonMode::Split));

        if(live)
        {
            postFxRuntimeSourceLabel_->setToolTip(
                "Live Game Capture — Display/LDR approximation. In BO3 Runtime mode the displayed frame is approximately reconstructed into the BO3 runtime color domain; it is not raw resolvedScene HDR.");
        }
        else if (hdr && preview_)
        {
            postFxRuntimeSourceLabel_->setToolTip(
                QString("True scene-linear HDR t0 source. Mean luminance: %1, peak luminance: %2. Values above 1.0 are preserved into the BO3 resolvedScene simulation.")
                    .arg(preview_->renderer().SourceHdrMeanLuminance(), 0, 'f', 4)
                    .arg(preview_->renderer().SourceHdrPeakLuminance(), 0, 'f', 4));
        }
        else
        {
            postFxRuntimeSourceLabel_->setToolTip(
                "LDR approximation. PNG/JPEG/BMP/TIFF are already display-encoded/tone-mapped and cannot preserve BO3 resolvedScene HDR values above 1.0. Load a scene-linear EXR for the accurate runtime path.");
        }
    }

    void selectLiveCaptureWindow()
    {
        if(!preview_) return;
        if(selectedPreviewMode() != PreviewMode::HLSL && selectedPreviewMode() != PreviewMode::PostFX)
        {
            if(QMessageBox::question(this, "Live Game Capture",
                "Live Game Capture is supported for HLSL and PostFX preview. Switch to generic HLSL preview now?") != QMessageBox::Yes)
            {
                QSignalBlocker blocker(sourceModeCombo_);
                sourceModeCombo_->setCurrentIndex(0);
                return;
            }
            selectPreviewMode(PreviewMode::HLSL);
        }

        QString initError;
        if(!preview_->ensureInitialized(initError))
        {
            QMessageBox::critical(this, "DirectX initialization failed", initError);
            return;
        }
        QString supportReason;
        if(!bo3::LiveWindowCapture::isSupported(&supportReason))
        {
            QMessageBox::warning(this, "Live Game Capture", supportReason);
            return;
        }
        const auto windows = bo3::LiveWindowCapture::visibleWindows(
            reinterpret_cast<HWND>(winId()));
        if(windows.isEmpty())
        {
            QMessageBox::information(this, "Live Game Capture", "No visible capturable application windows were found.");
            return;
        }

        QDialog dialog(this);
        dialog.setWindowTitle("Select Live Capture Window");
        dialog.resize(680, 170);
        auto* layout = new QVBoxLayout(&dialog);
        auto* help = new QLabel(
            "External Windows Graphics Capture + D3D11 is used. No code is injected into the game. Borderless/windowed mode is usually more reliable than exclusive fullscreen.");
        help->setWordWrap(true);
        layout->addWidget(help);
        auto* combo = new QComboBox();
        for(const auto& window : windows)
            combo->addItem(window.title, QVariant::fromValue<qulonglong>(
                reinterpret_cast<qulonglong>(window.hwnd)));
        const int bo3Index = combo->findText("Call of Duty: Black Ops III", Qt::MatchContains);
        if(bo3Index >= 0) combo->setCurrentIndex(bo3Index);
        layout->addWidget(combo);
        auto* buttons = new QDialogButtonBox(QDialogButtonBox::Ok | QDialogButtonBox::Cancel);
        buttons->button(QDialogButtonBox::Ok)->setText("Start Capture");
        connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
        connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
        layout->addWidget(buttons);
        if(dialog.exec() != QDialog::Accepted)
        {
            if(!preview_->renderer().LiveCaptureActive())
            {
                QSignalBlocker blocker(sourceModeCombo_);
                sourceModeCombo_->setCurrentIndex(0);
            }
            return;
        }

        const HWND target = reinterpret_cast<HWND>(
            combo->currentData().toULongLong());
        std::wstring captureError;
        if(!preview_->renderer().StartLiveCapture(target, captureError))
        {
            QMessageBox::warning(this, "Live Game Capture", ToQString(captureError));
            QSignalBlocker blocker(sourceModeCombo_);
            sourceModeCombo_->setCurrentIndex(0);
            return;
        }
        {
            QSignalBlocker blocker(sourceModeCombo_);
            sourceModeCombo_->setCurrentIndex(2);
        }
        sourceImagePath_.clear();
        refreshPostFxRuntimeUi();
        statusBar()->showMessage(
            "Source: LIVE BO3 WINDOW — LDR APPROX (Windows Graphics Capture, external/non-invasive)", 6000);
    }

    void stopLiveCapture()
    {
        if(!preview_) return;
        preview_->renderer().StopLiveCapture();
        if(sourceModeCombo_)
        {
            QSignalBlocker blocker(sourceModeCombo_);
            sourceModeCombo_->setCurrentIndex(0);
        }
        refreshPostFxRuntimeUi();
        statusBar()->showMessage("Live game capture stopped; captured SRV released", 3500);
    }

    void openTexture(bool depth, bool sceneLinearOnly = false)
    {
        const QString filter = depth
            ? "Images (*.png *.jpg *.jpeg *.bmp *.tif *.tiff);;All files (*.*)"
            : (sceneLinearOnly
                ? "Scene-linear HDR (*.exr);;All files (*.*)"
                : "PostFX source (*.exr *.png *.jpg *.jpeg *.bmp *.tif *.tiff);;Scene-linear HDR (*.exr);;LDR images (*.png *.jpg *.jpeg *.bmp *.tif *.tiff);;All files (*.*)");
        const QString path = QFileDialog::getOpenFileName(this,
            depth ? "Open depth map t1" : (sceneLinearOnly ? "Open scene-linear EXR source" : "Open source image t0"),
            currentDirectory(), filter);
        if (path.isEmpty())
        {
            if(!depth && sourceModeCombo_ && sourceImagePath_.isEmpty())
            {
                QSignalBlocker blocker(sourceModeCombo_);
                sourceModeCombo_->setCurrentIndex(0);
            }
            return;
        }
        loadTexture(path, depth);
    }

    void loadTexture(const QString& path, bool depth)
    {
        QString initError;
        if (!preview_->ensureInitialized(initError))
        {
            QMessageBox::critical(this, "DirectX initialization failed", initError);
            return;
        }
        std::wstring error;
        if (!preview_->renderer().LoadTexture(fs::path(path.toStdWString()), depth, error))
            QMessageBox::warning(this, "Texture load failed", ToQString(error));
        else
        {
            if (!depth)
            {
                sourceImagePath_ = QFileInfo(path).absoluteFilePath();
                if(sourceModeCombo_)
                {
                    QSignalBlocker blocker(sourceModeCombo_);
                    sourceModeCombo_->setCurrentIndex(
                        preview_->renderer().SourceIsLinearHDR() ? 1 : 0);
                }
                refreshPostFxRuntimeUi();
                if(selectedPreviewMode() == PreviewMode::PostFX) compileEditor();
            }
            statusBar()->showMessage(QString("Loaded %1 as %2%3")
                .arg(QFileInfo(path).fileName(), depth ? "t1 depth" : "t0 source",
                     (!depth && preview_->renderer().SourceIsLinearHDR()) ? " (scene-linear HDR)" : ""), 4000);
        }
    }

