    void reloadShadertoyChannelTexture(int channel)
    {
        if (!preview_ || channel < 0 || channel >= kShadertoyChannelCount) return;
        const QString path = ToQString(preview_->renderer().GetShadertoyChannelPath(channel));
        if (path.isEmpty()) return;
        loadShadertoyChannelTextureFromPath(channel, path);
    }

    void clearShadertoyChannelTexture(int channel)
    {
        if (!preview_) return;
        preview_->renderer().ClearShadertoyChannelTexture(channel);
        refreshShadertoyChannelUi();
        if(selectedPreviewMode() == PreviewMode::PostFX) compileEditor();
        statusBar()->showMessage(QString("Cleared iChannel%1").arg(channel), 2500);
    }

    void refreshShadertoyChannelUi()
    {
        if (!preview_) return;
        std::array<bool, kShadertoyChannelCount> required{{false,false,false,false}};
        for (const int channel : preview_->renderer().RequiredShadertoyChannels())
            if (channel >= 0 && channel < kShadertoyChannelCount) required[static_cast<size_t>(channel)] = true;
        for (int channel = 0; channel < kShadertoyChannelCount; ++channel)
        {
            if (shadertoyChannelRepeatBoxes_[channel])
            {
                QSignalBlocker blocker(shadertoyChannelRepeatBoxes_[channel]);
                shadertoyChannelRepeatBoxes_[channel]->setChecked(preview_->renderer().GetShadertoyChannelRepeat(channel));
            }
            if (shadertoyChannelFlipBoxes_[channel])
            {
                QSignalBlocker blocker(shadertoyChannelFlipBoxes_[channel]);
                shadertoyChannelFlipBoxes_[channel]->setChecked(preview_->renderer().GetShadertoyChannelFlipY(channel));
            }
            if (!shadertoyChannelPathLabels_[channel]) continue;
            const QString path = ToQString(preview_->renderer().GetShadertoyChannelPath(channel));
            if (path.isEmpty())
            {
                if (required[static_cast<size_t>(channel)])
                {
                    shadertoyChannelPathLabels_[channel]->setText("⚠ REQUIRED - no texture loaded");
                    shadertoyChannelPathLabels_[channel]->setStyleSheet("QLabel { color:#FFD0D0; border:1px solid #A54B4B; border-radius:5px; background:#2A1719; font-weight:600; }");
                    shadertoyChannelPathLabels_[channel]->setToolTip(QString("This shader samples iChannel%1. Load the exact Shadertoy input texture or the preview will be wrong/blank.").arg(channel));
                }
                else
                {
                    shadertoyChannelPathLabels_[channel]->setText("No texture loaded");
                    shadertoyChannelPathLabels_[channel]->setStyleSheet("QLabel { color:#9AA3AE; border:1px dashed #4B5563; border-radius:5px; background:#171A1F; }");
                    shadertoyChannelPathLabels_[channel]->setToolTip(QString("Load the texture used by Shadertoy iChannel%1.").arg(channel));
                }
            }
            else
            {
                const UINT w = preview_->renderer().GetShadertoyChannelWidth(channel);
                const UINT h = preview_->renderer().GetShadertoyChannelHeight(channel);
                shadertoyChannelPathLabels_[channel]->setText(QString("✓ %1  (%2×%3)").arg(QFileInfo(path).fileName()).arg(w).arg(h));
                shadertoyChannelPathLabels_[channel]->setStyleSheet("QLabel { color:#DCE7F3; border:1px solid #3D6A8A; border-radius:5px; background:#18232B; }");
                shadertoyChannelPathLabels_[channel]->setToolTip(QDir::toNativeSeparators(path));
            }
        }
    }

    bool loadMaterialTextureFromPath(int logicalSlot, const QString& path)
    {
        if (path.isEmpty()) return false;
        QString initError;
        if (!preview_->ensureInitialized(initError))
        {
            QMessageBox::critical(this, "DirectX initialization failed", initError);
            return false;
        }
        std::wstring error;
        if (!preview_->renderer().LoadMaterialTexture(logicalSlot, fs::path(path.toStdWString()), error))
        {
            QMessageBox::warning(this, "Texture load failed", ToQString(error));
            refreshMaterialTextureUi();
            return false;
        }
        refreshMaterialTextureUi();
        statusBar()->showMessage(QString("Loaded %1 into %2").arg(QFileInfo(path).fileName()).arg(MaterialTextureSlotName(logicalSlot)), 3000);
        return true;
    }

    void browseMaterialTexture(int logicalSlot)
    {
        const QString title = QString("Load %1 texture").arg(MaterialTextureSlotName(logicalSlot));
        const QString path = QFileDialog::getOpenFileName(this, title, currentDirectory(), "Images (*.png *.jpg *.jpeg *.bmp *.tif *.tiff);;All files (*.*)");
        if (path.isEmpty()) return;
        loadMaterialTextureFromPath(logicalSlot, path);
    }

    void clearMaterialTexture(int logicalSlot, bool showStatus = true)
    {
        preview_->renderer().ClearMaterialTexture(logicalSlot);
        if (showStatus)
            statusBar()->showMessage(QString("Cleared %1").arg(MaterialTextureSlotName(logicalSlot)), 2500);
        refreshMaterialTextureUi();
    }

    void refreshMaterialTextureUi()
    {
        if (!preview_) return;
        for (int i = 0; i < kMaterialTextureSlotCount; ++i)
        {
            if (materialTextureBindingBoxes_[i])
            {
                const UINT bind = preview_->renderer().GetMaterialTextureBinding(i);
                QSignalBlocker blocker(materialTextureBindingBoxes_[i]);
                const int index = materialTextureBindingBoxes_[i]->findData(static_cast<int>(bind));
                if (index >= 0) materialTextureBindingBoxes_[i]->setCurrentIndex(index);
            }
            if (materialTexturePathLabels_[i])
            {
                const QString path = ToQString(preview_->renderer().GetMaterialTexturePath(i));
                if (path.isEmpty())
                {
                    materialTexturePathLabels_[i]->setText("Drop image here  •  or Browse...");
                    materialTexturePathLabels_[i]->setStyleSheet("QLabel { color:#9AA3AE; border:1px dashed #4B5563; border-radius:5px; background:#171A1F; }");
                    materialTexturePathLabels_[i]->setToolTip(QString("Drop an image here to use it as %1.").arg(MaterialTextureSlotName(i)));
                }
                else
                {
                    materialTexturePathLabels_[i]->setText(QString("✓  %1").arg(QFileInfo(path).fileName()));
                    materialTexturePathLabels_[i]->setStyleSheet("QLabel { color:#DCE7F3; border:1px solid #3D6A8A; border-radius:5px; background:#18232B; }");
                    materialTexturePathLabels_[i]->setToolTip(QDir::toNativeSeparators(path));
                }
            }
        }
    }

    void chooseIncludeRoot()
    {
        const QString dir = QFileDialog::getExistingDirectory(this, "Choose BO3 include root", includeRoot_.isEmpty() ? currentDirectory() : includeRoot_);
        if (dir.isEmpty()) return;
        includeRoot_ = QDir::toNativeSeparators(QFileInfo(dir).absoluteFilePath());
        includeRootLabel_->setText("Includes: " + includeRoot_);
        compileEditor();
    }

    bool handleDrop(const QMimeData* mime)
    {
        if (!mime || !mime->hasUrls()) return false;
        for (const QUrl& url : mime->urls())
        {
            if (!url.isLocalFile()) continue;
            QFileInfo info(url.toLocalFile());
            if (info.isDir())
            {
                includeRoot_ = QDir::toNativeSeparators(info.absoluteFilePath());
                includeRootLabel_->setText("Includes: " + includeRoot_);
                compileEditor();
                statusBar()->showMessage("Include root set from dropped folder", 3000);
                return true;
            }
            const QString suffix = info.suffix().toLower();
            if (QStringList{"obj","fbx","xmodel_export","xmodel"}.contains(suffix))
            {
                loadCustomModelFromPath(info.absoluteFilePath());
                return true;
            }
            if (suffix == "hlsl" || suffix == "hlsli" || suffix == "h")
            {
                if (maybeSave()) openShader(info.absoluteFilePath());
                return true;
            }
            if (suffix == "exr")
            {
                // In PostFX mode an EXR is a true scene-linear t0 source for
                // resolvedScene parity. In Sky/material workflows retain the
                // existing environment-drop behavior.
                if (previewModeCombo_ && selectedPreviewMode() == PreviewMode::PostFX)
                    loadTexture(info.absoluteFilePath(), false);
                else
                    loadEnvironmentTextureFromPath(info.absoluteFilePath());
                if (previewDock_) { previewDock_->show(); previewDock_->raise(); }
                return true;
            }
            if (QStringList{"png","jpg","jpeg","bmp","tif","tiff"}.contains(suffix))
            {
                loadTexture(info.absoluteFilePath(), false);
                return true;
            }
            if (suffix == "zip")
            {
                installUpdatePackage(info.absoluteFilePath());
                return true;
            }
        }
        return false;
    }

    void chooseCustomModel()
    {
        const QString path = QFileDialog::getOpenFileName(this, "Import Preview Model", currentDirectory(),
            "Preview models (*.obj *.fbx *.xmodel_export *.xmodel);;Wavefront OBJ (*.obj);;FBX ASCII (*.fbx);;XMODEL_EXPORT (*.xmodel_export *.xmodel);;All files (*.*)");
        if(!path.isEmpty()) loadCustomModelFromPath(path);
    }

    bool loadCustomModelFromPath(const QString& path)
    {
        if(!preview_) return false;
        QString initError;
        if(!preview_->ensureInitialized(initError)) { QMessageBox::critical(this,"DirectX initialization failed",initError); return false; }
        std::wstring error;
        if(!preview_->renderer().LoadCustomModel(fs::path(path.toStdWString()), error))
        {
            QMessageBox::warning(this,"Model import failed",ToQString(error));
            return false;
        }
        if(meshCombo_)
        {
            QSignalBlocker blocker(meshCombo_); meshCombo_->setCurrentIndex(4);
        }
        syncSceneControlsFromRenderer(); updateCameraUi();
        statusBar()->showMessage(QString("Custom model loaded: %1").arg(QFileInfo(path).fileName()),3500);
        return true;
    }

    void clearCustomModel()
    {
        if(!preview_) return;
        preview_->renderer().ClearCustomModel();
        if(meshCombo_){QSignalBlocker blocker(meshCombo_);meshCombo_->setCurrentIndex(0);}
        syncSceneControlsFromRenderer(); updateCameraUi();
        statusBar()->showMessage("Using built-in sphere preview",2500);
    }

    void applyLightingPreset(int index)
    {
        if(!preview_) return;
        auto& r=preview_->renderer();
        switch(index)
        {
        case 1: // Daylight
            r.SetFulbright(false); r.SetLightAngles(125.0f,55.0f); r.SetLightIntensity(1.45f); r.SetAmbientIntensity(0.38f); r.SetShadowStrength(0.58f); r.SetLookdevExposureEV(0.25f); break;
        case 2: // Overcast
            r.SetFulbright(false); r.SetLightAngles(160.0f,70.0f); r.SetLightIntensity(0.58f); r.SetAmbientIntensity(0.82f); r.SetShadowStrength(0.14f); r.SetLookdevExposureEV(0.45f); break;
        case 3: // Dark interior
            r.SetFulbright(false); r.SetLightAngles(35.0f,28.0f); r.SetLightIntensity(0.48f); r.SetAmbientIntensity(0.08f); r.SetShadowStrength(0.72f); r.SetLookdevExposureEV(-0.35f); break;
        case 4: // Fullbright
            r.SetFulbright(true); r.SetLookdevExposureEV(0.0f); break;
        default: // Studio
            r.SetFulbright(false); r.SetLightAngles(135.0f,45.0f); r.SetLightIntensity(1.2f); r.SetAmbientIntensity(0.42f); r.SetShadowStrength(0.50f); r.SetLookdevExposureEV(0.20f); break;
        }
        syncSceneControlsFromRenderer();
    }

